window.CATALOGUE={"mode":"discovery","families":{"F01":"Option models \u0026 surfaces","F02":"Numerical pricing \u0026 exotics","F03":"Volatility \u0026 tail risk","F04":"Hedging \u0026 volatility derivatives","F05":"Fixed income \u0026 interest rates","F06":"Credit \u0026 incomplete markets","F07":"International, FX \u0026 commodities","F08":"Cross-sectional pricing \u0026 SDF","F09":"Predictability \u0026 machine learning","F10":"Consumption \u0026 equity valuation","F11":"Macro-finance \u0026 policy","F12":"Portfolios \u0026 market frictions"},"projects":[{"id":"A01.01.01","title":"Testing the CAPM across Size and Value Portfolios","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"Does market beta account for differences in average excess returns across size and book-to-market portfolios? How sensitive is the conclusion to test assets and inference?","motivation":"The CAPM imposes a joint restriction on expected returns, not merely on their comovement with the market. Size and value portfolios provide a deliberately challenging test of that restriction. An industry panel changes the test assets without pretending that the underlying stocks are independent.","prereq":"OLS, multivariate statistics, portfolio theory, Python statsmodels/NumPy.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.01.01"},{"id":"A01.01.02","title":"The Low-Beta Anomaly and the Risk-Return Trade-Off","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"Is the security market line flatter than the CAPM prediction across publicly available beta-sorted portfolios, and is the low-beta evidence robust to size and alternative factor controls?","motivation":"A flatter security market line challenges the CAPM prediction that higher market exposure earns a proportionally higher expected excess return. Formation-beta portfolios make this pattern visible, while size controls and the published betting-against-beta factor help distinguish different empirical objects.","prereq":"CAPM, multifactor models, regression, portfolio data and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.01.02"},{"id":"A01.02.01","title":"Three Factors or Five? Comparing Fama-French Asset Pricing Models","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"Does the Fama-French five-factor model improve pricing of US industry and characteristic portfolios relative to the three-factor model, and are the gains stable across samples? Do the additional factors have explanatory power conditional on common market, size and value factors?","motivation":"A larger factor model can explain more return variation without improving the pricing of expected returns. A further complication is that published FF3 and FF5 need not share identical size factors. A literal comparison and a deliberately nested comparison answer different questions.","prereq":"Linear regression, matrix algebra, portfolio returns, multivariate hypothesis tests, pandas/statsmodels. No individual stock database necessary.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.02.01"},{"id":"A01.02.02","title":"Momentum and the Limits of Fundamental Factor Models","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"Does a traded momentum factor improve the pricing of momentum portfolios and independent industry portfolios relative to FF3 and FF5, and how stable is the improvement?","motivation":"Momentum is a useful test of whether fundamental factor models price return patterns not already spanned by their factors. Momentum-sorted portfolios and industries provide different test-asset constructions but share underlying securities. A successful addition need not identify a structural risk.","prereq":"Asset pricing factors, multivariate regression, inference and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.02.02"},{"id":"A01.03.01","title":"Which Stock Return Anomalies Survive Standard Factor Adjustment?","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"conditional","question":"Which prespecified replicated anomalies retain nonzero alphas after common factor adjustment and dependence-aware multiplicity controls?","motivation":"Many published anomalies share securities, signals and sample periods. A credible comparison of model-adjusted returns requires a fixed universe and an explicit treatment of multiplicity, not a ranking selected after inspecting t-statistics.","prereq":"Factor models, HAC, multiple testing, data processing, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"OSAP release, signal metadata, permissions and common factor sample.","state":"description","href":"topic.html?id=A01.03.01"},{"id":"A01.03.02","title":"The Stability of Anomaly Returns after Publication","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"conditional","question":"How do anomaly returns and factor-adjusted alphas change across original-sample, post-sample pre-publication and post-publication windows in a fixed set of documented predictors?","motivation":"Anomaly returns may attenuate after the discovery sample or after publication. These are different comparisons. Publication dates are not randomly assigned, and a reconstructed return history is not a record of what investors knew in real time.","prereq":"Panel econometrics, factor pricing, data cleaning, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Event studies"],"data_note":"Matching OSAP release and documented publication dates for at least 20 signals.","state":"description","href":"topic.html?id=A01.03.02"},{"id":"A01.04.01","title":"Factor Spanning and the Economic Value of Additional Factors","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"Which additional traded factors improve the mean-variance opportunity set beyond FF3, and do gains survive out-of-sample estimation?","motivation":"Adding a traded factor can enlarge the mean-variance opportunity set even when it does not resolve pricing errors on a chosen test-asset panel. Estimation error, leverage and transaction costs may erode the apparent in-sample improvement.","prereq":"Mean-variance theory, factor regressions, covariance estimation and bootstrap.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.04.01"},{"id":"A01.04.02","title":"Principal Components versus Observable Asset Pricing Factors","area":"Asset Pricing","family":"F08","difficulty":3,"gate":"pending","question":"At equal factor dimension, do principal-component factors estimated on training assets produce smaller held-out pricing errors than observable FF factors?","motivation":"Principal components extract directions of high return variance, whereas an asset-pricing model must explain mean returns. An equal-dimensional, frozen comparison on later dates and distinct portfolio constructions separates covariance reconstruction from pricing.","prereq":"Linear algebra, factor models, regression, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A01.04.02"},{"id":"A02.01.01","title":"Can Valuation Ratios Predict the Equity Premium?","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Can lagged dividend-price and earnings-price ratios improve monthly US equity excess-return forecasts over the historical mean, and is their performance stable across decades? Assess whether the gains remain after accounting for parameter uncertainty and timing conventions.","motivation":"Equity prices summarize both expected cash flows and the rates used to discount them. A high dividend-price ratio may therefore signal a higher expected equity premium, weaker expected dividend growth, or both. Estimating that relation in historical data is not enough: investors must form forecasts without future information. This project asks whether valuation ratios add predictive information beyond a recursively estimated historical mean and whether that gain survives changes in the sample.","prereq":"OLS, time-series forecasting, return conventions, basic present-value theory, Python. No proprietary predictor database required.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.01.01"},{"id":"A02.01.02","title":"Long-Horizon Stock Return Predictability and Statistical Inference","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"How does inference about dividend-price predictability change from one to three and twelve months after accounting for overlap, persistent regressors and joint testing across horizons?","motivation":"A rising long-horizon regression coefficient need not be evidence of stronger economic predictability. Aggregating returns makes successive dependent variables share observations, and persistent valuation ratios amplify finite-sample distortion. This thesis studies inference, not a horse race between forecasting algorithms.","prereq":"Time-series econometrics, HAC, Monte Carlo and Python statsmodels. Advanced level.","design":"Empirical application","tags":["Simulation \u0026 Monte Carlo","Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.01.02"},{"id":"A02.02.01","title":"Interest Rates and the Predictability of Stock Market Excess Returns","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do short rates and the term spread add out-of-sample information about monthly equity excess returns beyond a dividend-price benchmark and the historical mean?","motivation":"Interest rates may proxy discount-rate variation or monetary conditions, but an in-sample association does not establish incremental forecasting value. The key comparison is against a valuation-only model using the same origins, return definition and timing.","prereq":"Time-series econometrics, bond yields, equity risk premia and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.02.01"},{"id":"A02.02.02","title":"Financial Conditions and Time-Varying Expected Equity Returns","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do financial-conditions indices provide incremental out-of-sample information about aggregate equity excess returns beyond standard valuation predictors?","motivation":"Financial-conditions indices aggregate many signals and may describe risk-bearing capacity. But revisions and asynchronous release dates can manufacture apparent predictive content. The empirical contribution is a transparent availability-aware comparison, not a causal claim about monetary policy.","prereq":"Asset pricing, predictive regressions, HAC, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.02.02"},{"id":"A02.03.01","title":"Combining Equity Premium Forecasts","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Can simple forecast combinations outperform individual predictive regressions and the historical mean in a genuinely recursive evaluation?","motivation":"Forecast combinations diversify parameter and model uncertainty without requiring a large joint regression. Adaptive weights may instead chase noise. The thesis separates combination benefits from extra opportunities to tune after the fact.","prereq":"OLS, forecast evaluation, time-series econometrics, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.03.01"},{"id":"A02.03.02","title":"Structural Instability in Equity Premium Predictability","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do rolling or discounted-window predictive regressions outperform expanding estimates when equity premium predictability is unstable?","motivation":"A short estimation window adapts to structural change but loses precision when predictability is stable. The thesis identifies that bias-variance trade-off using a controlled simulation and a common-date empirical comparison.","prereq":"Time-series regressions, rolling estimation, bootstrap, Python.","design":"Empirical application","tags":["Simulation \u0026 Monte Carlo","Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.03.02"},{"id":"A02.04.01","title":"Does Return Predictability Translate into Better Portfolio Decisions?","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do recursive equity-premium forecasts improve realized certainty equivalent and risk-adjusted portfolio performance relative to historical-mean and fixed-weight policies?","motivation":"Statistical forecast gains need not survive estimation error, risk limits, turnover and transaction costs. A controlled portfolio experiment isolates the economic value of the mean forecast, holding variance and trading conventions fixed.","prereq":"Predictive regressions, portfolio choice, time series and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.04.01"},{"id":"A02.04.02","title":"Predicting the Distribution Rather Than the Mean of Stock Returns","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"Do valuation and implied-volatility indicators improve lower-tail monthly market excess-return forecasts relative to unconditional historical and rolling location-scale benchmarks?","motivation":"Expected returns alone do not describe downside exposure. Conditional quantiles target tail outcomes without assuming a full parametric distribution, but lower-tail samples are sparse and quantile crossing complicates interpretation.","prereq":"Quantile regression, forecasting, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A02.04.02"},{"id":"A03.01.01","title":"The Equity Premium Puzzle: Theory and Quantitative Evidence","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"pending","question":"Can a CRRA stochastic discount factor with plausible risk aversion and discounting simultaneously explain the US market excess return and the average risk-free rate? How sensitive is the answer to consumption measurement and time aggregation?","motivation":"The equity premium and the low safe rate impose different restrictions on the same marginal utility process. A joint exercise is more informative than choosing a risk aversion coefficient that matches only one return.","prereq":"Expected utility, stochastic discount factors, covariance/lognormal algebra, empirical return construction, Python. No structural estimation package required.","design":"Empirical application","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Calibration \u0026 estimation","Regression \u0026 inference"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A03.01.01"},{"id":"A03.01.02","title":"The Risk-Free Rate Puzzle under Time-Additive Utility","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"pending","question":"Can time-additive power utility with plausible risk aversion and discounting reproduce both the mean and time variation of real short rates given observed US consumption growth?","motivation":"The mean and variability of real safe rates test both impatience and the dynamics of marginal utility. Predictable growth can generate conditional rate variation even with constant preferences.","prereq":"Expected utility, macro-finance, lognormal moments and time-series regression.","design":"Empirical application","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Calibration \u0026 estimation","Time-series forecasting","Regression \u0026 inference"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A03.01.02"},{"id":"A03.02.01","title":"Habit Formation and Time-Varying Equity Risk Premia","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"not_required","question":"How does the dependence of surplus consumption on consumption shocks change conditional risk prices, equity premia and risk-free rates relative to a CRRA benchmark?","motivation":"Even when consumption growth and the surplus-state transition have unchanged marginal distributions, their coupling can alter the covariance of marginal utility with payoffs. This isolates a mechanism distinct from a change in unconditional volatility.","prereq":"Consumption-based asset pricing, Markov chains, linear algebra, numerical methods and Python.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Stochastic processes","Simulation \u0026 Monte Carlo","Cash-flow valuation"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.02.01"},{"id":"A03.02.02","title":"Habit, Risk Aversion and the Volatility of Asset Prices","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"not_required","question":"How does surplus-consumption persistence interact with risk aversion to generate price-dividend and return volatility, and what trade-off emerges for the risk-free rate?","motivation":"Persistent habit-related states can change the valuation of many future cash flows, not merely the price of a one-period shock. The same surplus distribution can therefore support different valuation dynamics.","prereq":"Consumption-based asset pricing, Markov chains, matrix algebra and Python.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Stochastic processes","Cash-flow valuation","Simulation \u0026 Monte Carlo","Factor models \u0026 SDF"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.02.02"},{"id":"A03.03.01","title":"Epstein-Zin Preferences and the Separation of Risk Aversion from Intertemporal Substitution","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"not_required","question":"How do risk aversion and the elasticity of intertemporal substitution independently affect equilibrium prices, and what changes when consumption growth becomes predictable?","motivation":"Time-additive power utility links relative risk aversion to the willingness to substitute consumption over time. Recursive utility breaks this restriction, yet its pricing implications depend on the distribution of consumption growth and on continuation wealth. The project isolates preference effects in an iid economy before introducing a predictable growth state, rather than treating a richer calibration as evidence of a particular economic mechanism.","prereq":"Intertemporal utility, Euler equations, Markov chains, lognormal moments and numerical root finding.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Stochastic processes","Calibration \u0026 estimation","Cash-flow valuation"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.03.01"},{"id":"A03.03.02","title":"Long-Run Consumption Risk and the Equity Premium","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"not_required","question":"Holding the unconditional distribution of consumption growth fixed, how do persistence of expected growth and recursive preferences jointly change equity premia, valuation volatility and the risk-free rate?","motivation":"Persistent expected growth changes the distribution of multi-period consumption without requiring more one-period volatility. Recursive preferences make continuation risk relevant, allowing a direct comparison of long-run and contemporaneous risk.","prereq":"Recursive preferences, Markov chains, asset pricing, nonlinear equations and numerical linear algebra.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Stochastic processes","Calibration \u0026 estimation","Cash-flow valuation","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.03.02"},{"id":"A03.04.01","title":"Rare Disasters and the Joint Behavior of Equity and Bond Returns","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"not_required","question":"How do disaster probability, severity and cash-flow exposure jointly affect equity premia, real safe rates and returns on defaultable or nominal bond claims?","motivation":"Disasters affect both the pricing kernel and cash-flow payoffs. The same shock can raise the price of a safe real payoff while reducing the value of an exposed dividend or defaultable payoff.","prereq":"Consumption-based pricing, probability mixtures, numerical simulation, Python.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Tail risk \u0026 distributions","Simulation \u0026 Monte Carlo","Cash-flow valuation"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.04.01"},{"id":"A03.04.02","title":"Limited Market Participation and Consumption-Based Pricing","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"not_required","question":"How does shareholder consumption exposure to aggregate dividend shocks affect the equity premium and risk-free rate in a transparent limited-participation pricing experiment?","motivation":"Asset pricing depends on the consumption exposure of the marginal investor. Changing shareholder consumption covariance with dividends can alter priced risk even when the aggregate dividend distribution stays fixed.","prereq":"Consumption-based pricing, lognormal moments, Python.","design":"Simulation","tags":["Equilibrium \u0026 preferences","Factor models \u0026 SDF","Cash-flow valuation","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A03.04.02"},{"id":"A04.01.01","title":"Expected Economic Growth and the Dynamics of Equity Risk Premia","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"pending","question":"Do published US real GDP growth forecasts predict future equity excess returns beyond valuation ratios, and does incremental predictive performance survive chronological evaluation?","motivation":"Survey forecasts separate expected output growth from realized economic news. Their incremental predictive content tests conditional expected returns, not whether growth shocks cause equity returns.","prereq":"Asset pricing, forecasting regressions, date handling and Python pandas/statsmodels.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A04.01.01"},{"id":"A04.01.02","title":"Macroeconomic Forecast Disagreement and Equity Market Risk","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"conditional","question":"Does forecast disagreement about next-quarter real output growth add predictive information about subsequent equity volatility beyond past volatility and mean expected growth?","motivation":"Cross-sectional disagreement about future output can contain information that a mean forecast misses. Disagreement measures heterogeneity, not the conditional variance of growth or a structural uncertainty shock.","prereq":"Financial econometrics, macro data, forecasting, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"SPF forecast dispersion and mean growth at the same horizon, with release dates.","state":"description","href":"topic.html?id=A04.01.02"},{"id":"A04.02.01","title":"Inflation Risk and the Cross-Section of Equity Returns","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"pending","question":"Which industry and characteristic portfolios have the strongest nominal and real return exposure to unexpected CPI inflation, and is the cross-sectional relation between inflation beta and average excess return robust to market beta?","motivation":"Inflation changes purchasing power and may also be associated with cash-flow or discount-rate news. Comparing nominal and real exposures with a market control separates accounting from descriptive cross-sectional differences.","prereq":"Asset pricing, macroeconomic data, regression, time-series inference and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Equilibrium \u0026 preferences"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A04.02.01"},{"id":"A04.02.02","title":"Are Stocks and Bonds Effective Inflation Hedges?","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"pending","question":"How do equity and nominal Treasury holding returns covary with realized and unexpected inflation, and does their effectiveness as purchasing-power hedges vary across horizons?","motivation":"An asset protects purchasing power only to the extent that holding returns respond favorably to inflation. A yield change is not a bond return, and hedge performance depends on how maturities age.","prereq":"Fixed income, return compounding, time-series econometrics, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A04.02.02"},{"id":"A04.03.01","title":"Monetary Policy Surprises and the Stock Market","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"conditional","question":"How strongly do US equity prices respond to unexpected shifts in the expected policy-rate path around FOMC communications, and does the response differ between statements and press conferences? Assess conditional associations without automatically assigning a causal structural policy shock interpretation.","motivation":"Monetary policy communications change expectations about short rates and the economic outlook. Measuring price changes in short announcement windows reduces contamination from unrelated news, but rate movements may still reflect information disclosed by the central bank. Comparing statements and press conferences can reveal differences in conditional market responses without assuming that the measured surprises are pure structural shocks.","prereq":"OLS and robust inference, monetary policy basics, event study, pandas/statsmodels; PCA optional. No proprietary tick data needed if public extract is usable.","design":"Empirical application","tags":["Regression \u0026 inference","Event studies"],"data_note":"USMPD event and surprise workbooks; matched equity windows, units and rights.","state":"description","href":"topic.html?id=A04.03.01"},{"id":"A04.03.02","title":"Monetary Policy and the Joint Response of Nominal and Real Yields","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"conditional","question":"How do the matched-maturity nominal and real Treasury yield responses to FOMC surprises vary with horizon and communication window, and what is the associated breakeven response?","motivation":"Joint movements of nominal and real yields describe the inflation-compensation component of monetary announcement responses. A valid comparison requires the same event, maturity and response window.","prereq":"Bond yields, regression, event studies, Python/R.","design":"Empirical application","tags":["Regression \u0026 inference","Fixed income \u0026 curves","Event studies"],"data_note":"USMPD: same-window, same-maturity nominal and real yields, plus surprise data.","state":"description","href":"topic.html?id=A04.03.02"},{"id":"A04.04.01","title":"Economic Policy Uncertainty and Equity Market Risk","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"pending","question":"Does economic policy uncertainty improve forecasts of future equity market variance beyond lagged variance and VIX?","motivation":"News-based economic policy uncertainty may predict future risk beyond persistence and option prices. The question is incremental information under realistic publication timing, not whether uncertainty structurally causes volatility.","prereq":"Volatility proxies, predictive regression, forecast evaluation, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A04.04.01"},{"id":"A04.04.02","title":"Financial Stress and the Stock-Bond Correlation","area":"Asset Pricing","family":"F11","difficulty":2,"gate":"pending","question":"Does the stock-bond return correlation vary with prior financial stress, and does that variation change the diversification benefit of a fixed stock-bond portfolio?","motivation":"Financial stress can change the joint distribution of stock and bond returns. A correlation shift alone does not establish whether a fixed allocation becomes riskier, because marginal variances also move.","prereq":"Fixed income, covariance estimation, time-series econometrics and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A04.04.02"},{"id":"A05.01.01","title":"Gaussian and Square-Root Interest Rate Models: Theory and Empirical Performance","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Do square-root rate innovations improve the fit and predictive distribution of US short-rate proxies relative to Gaussian mean reversion?","motivation":"Short-rate models differ in the support and conditional dispersion of their innovations. A square-root diffusion can accommodate state-dependent volatility, whereas a Gaussian diffusion allows negative rates. The economic question is whether the richer distribution improves predictive density on an identical observed proxy, not whether a model can price bonds after an unrelated calibration.","prereq":"Stochastic calculus, likelihood, noncentral chi-square distributions, numerical optimization and Python SciPy.","design":"Empirical application","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Time-series forecasting","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.01.01"},{"id":"A05.01.02","title":"Can One-Factor Interest Rate Models Explain the Dynamics of the Yield Curve?","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"How much variation across Treasury maturities can one affine factor explain, and which systematic curve movements remain unexplained?","motivation":"A one-factor affine term structure forces all cross-sectional yield movements to share a single loading vector. Treasury curves may bend or twist independently. The project measures which dimensions remain unexplained and whether a model-implied loading restriction is costly relative to unconstrained statistical factors.","prereq":"Bond pricing, linear algebra, least squares and Python; stochastic calculus helpful.","design":"Empirical application","tags":["Stochastic processes","Calibration \u0026 estimation","Regression \u0026 inference","Fixed income \u0026 curves","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.01.02"},{"id":"A05.01.03","title":"Interest Rate Volatility and the Performance of Affine Term Structure Models","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Does level-dependent short-rate volatility improve conditional variance forecasts and account for the state dependence of Treasury yield changes?","motivation":"A conditional mean model can fit average rate movements but miss state-dependent fluctuations. This matters for risk management across maturities. Compare the variance forecasts implied by constant and level-dependent diffusion coefficients against a flexible statistical benchmark on the same eligible rate history.","prereq":"Stochastic processes, likelihood, fixed income and time-series forecasting.","design":"Empirical application","tags":["Stochastic processes","Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.01.03"},{"id":"A05.02.01","title":"Modeling and Forecasting the Yield Curve with the Dynamic Nelson-Siegel Model","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Does dynamic Nelson-Siegel improve monthly nominal zero-yield forecasts at 1, 3 and 12 months relative to a no-change forecast, and at which maturities and horizons does it help?","motivation":"A yield curve evolves through persistent changes in level, slope and curvature. Dynamic Nelson-Siegel summarizes that shape in a small factor vector. The test is whether forecasting these factors adds information relative to the current observed yield at the same maturity.","prereq":"Fixed income, linear regression, AR/VAR basics, time-series validation, Python. No bond transaction database required.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.02.01"},{"id":"A05.02.02","title":"Principal Components and the Dynamics of Government Bond Yields","area":"Asset Pricing","family":"F05","difficulty":1,"gate":"pending","question":"How stable are the dimensionality and loading shapes of government yield curves across the US and euro area and across time?","motivation":"Curve shocks across maturities often appear low-dimensional. Whether that representation remains stable across economies and episodes matters for interpreting common rate risk. This study compares covariance eigenspaces, not the forecast performance of a dynamic model.","prereq":"Bond yields, covariance, eigenvectors, basic time series and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Fixed income \u0026 curves","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.02.02"},{"id":"A05.02.03","title":"Forecasting the Yield Curve: Econometric Models versus Machine Learning","area":"Asset Pricing","family":"F05","difficulty":3,"gate":"pending","question":"Does machine learning improve multi-horizon US yield-curve forecasts relative to random walk, autoregressive factors and dynamic Nelson-Siegel, after honest temporal validation?","motivation":"Flexible forecasting methods may learn nonlinear relations across the yield curve, but their apparent advantage can arise from extra information or leakage. Evaluate incremental predictive value relative to strong econometric benchmarks at the same origins, maturities and horizons.","prereq":"Fixed income, econometrics, regression/ML, Python and sklearn.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Machine learning","Fixed income \u0026 curves","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.02.03"},{"id":"A05.03.01","title":"The Predictability of Government Bond Excess Returns","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Can forward rates predict one-year government zero-coupon bond excess returns out of sample, relative to historical mean and slope predictors?","motivation":"Predictable variation in bond excess returns is evidence about time-varying compensation for bearing duration risk. The experiment asks whether forward rates improve real-time-feasible forecasting over simple alternatives, not whether a regression fitted on the whole sample is significant.","prereq":"Fixed income mathematics, regressions, HAC, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.03.01"},{"id":"A05.03.02","title":"Forward Rates and Time-Varying Bond Risk Premia","area":"Asset Pricing","family":"F05","difficulty":3,"gate":"pending","question":"Does a training-estimated Cochrane-Piazzesi-style common forward factor improve multi-maturity bond risk-premium forecasts, and are its weights and predictive gains stable across time?","motivation":"If expected bond returns share a common factor, a single combination of forward rates may summarize predictive variation across maturities. The project tests that parsimonious restriction and its stability; a tent-shaped coefficient profile is an empirical hypothesis, not a constraint.","prereq":"Fixed income, time-series regression, Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.03.02"},{"id":"A05.03.03","title":"Macroeconomic Expectations and the Predictability of Bond Returns","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Do real GDP growth and inflation expectations from the Survey of Professional Forecasters improve pseudo-out-of-sample forecasts of future Treasury excess returns beyond forward-rate factors?","motivation":"Forward rates embed both expectations and risk compensation. Survey forecasts may contribute independently measured information about future growth and inflation. The study evaluates incremental pseudo-out-of-sample predictability conditional on a yield-only benchmark and documented survey releases.","prereq":"Fixed income, predictive regressions, forecast evaluation, macro data.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.03.03"},{"id":"A05.04.01","title":"Understanding the Economic Determinants of the Bond Term Premium","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"Which observable macro-financial states are associated with the level and slope of published Treasury term-premium estimates, and how sensitive is the interpretation to the term-structure model?","motivation":"Observed long yields combine expected future short rates with compensation for risk, but the two components are not separately traded observables. Published model-based decompositions enable a disciplined descriptive investigation of which macro-financial states are associated with estimated term premia.","prereq":"Term-structure models, macro finance, regression, time-series inference.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Factor models \u0026 SDF","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.04.01"},{"id":"A05.04.02","title":"Inflation Risk and the Term Structure of Nominal and Real Interest Rates","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"How does the term structure of inflation compensation covary with survey inflation expectations and inflation uncertainty, and how much variation remains after accounting for available expectations proxies?","motivation":"Nominal and inflation-indexed yields jointly reveal market inflation compensation, but this is not a direct observation of expected inflation. Survey forecasts and uncertainty proxies help characterize its variation without assuming that the residual is a pure inflation risk premium.","prereq":"Bond pricing, inflation measurement, time series, macro finance.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.04.02"},{"id":"A05.04.03","title":"The Dynamics of the Yield Curve over the Business Cycle: US and European Evidence","area":"Asset Pricing","family":"F05","difficulty":2,"gate":"pending","question":"How similar are the level, slope and curvature dynamics of US Treasury and euro-area AAA government curves across the business cycle, and does conditioning on local activity alter cross-market co-movement?","motivation":"Global rate shocks can move different sovereign curves together, while local macro conditions affect each curve's shape. A common-date comparison reveals whether conditional co-movement is robust across two distinct government-bond markets without asserting that they have identical risk-free rates.","prereq":"Fixed income, macroeconomics, PCA, regression and time series.","design":"Empirical application","tags":["Regression \u0026 inference","Fixed income \u0026 curves","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A05.04.03"},{"id":"A06.01.01","title":"Dividend Growth Expectations and the Valuation of the Stock Market","area":"Asset Pricing","family":"F10","difficulty":1,"gate":"pending","question":"How sensitive are aggregate equity valuations to dividend growth and required returns, and which combinations are consistent with historical price-dividend ratios?","motivation":"A large price-dividend ratio can arise from strong expected dividend growth or a low required return. The valuation equation provides a disciplined way to display this ambiguity rather than assigning a historical ratio to one cause.","prereq":"Discounted cash flow, algebra, elementary statistics and Python. Foundation level.","design":"Empirical application","tags":["Cash-flow valuation","Equilibrium \u0026 preferences","Regression \u0026 inference"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A06.01.01"},{"id":"A06.01.02","title":"Do Long-Horizon Valuation Ratios Reflect Cash Flow or Discount Rate Variation?","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"pending","question":"How much of aggregate valuation-ratio variation is associated with expected future returns versus dividend growth, and how sensitive is this decomposition to the forecasting model and horizon?","motivation":"A valuation ratio can predict future returns, future dividends, or both. A finite-horizon present-value identity makes the role of terminal values and measurement errors explicit.","prereq":"Asset pricing, VAR, matrix algebra and Python; advanced time-series skills.","design":"Empirical application","tags":["Cash-flow valuation","Regression \u0026 inference","Time-series forecasting","Equilibrium \u0026 preferences"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A06.01.02"},{"id":"A06.02.01","title":"The Term Structure of Equity Yields: Evidence from Synthetic Dividend Strips","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"conditional","question":"What are the main level, slope and curvature patterns of US aggregate equity yields, and how do they differ in recessions versus expansions? Does subtracting nominal bond yields change the economic interpretation of the slope?","motivation":"The maturity profile of equity valuation reveals whether short and distant dividends are discounted differently. Synthetic strip estimates extend the horizon coverage, but their common estimation model constrains interpretation.","prereq":"Asset pricing SDF, bond yields, time-series statistics and PCA, Python. No licensed dividend strip data or full affine estimation required.","design":"Empirical application","tags":["Cash-flow valuation","Fixed income \u0026 curves","Regression \u0026 inference","PCA \u0026 latent factors"],"data_note":"GKK synthetic strip-yield archive, conventions, rights and common sample.","state":"description","href":"topic.html?id=A06.02.01"},{"id":"A06.02.02","title":"Equity Yield Curves across Investment Styles","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"conditional","question":"How do the level, slope and cyclicality of model-implied equity yields differ between high and low characteristic portfolios, especially value and growth?","motivation":"Style differences in equity valuation may vary substantially by horizon. A matched pair comparison avoids confounding the characteristic contrast with different dates and maturity coverage.","prereq":"Asset pricing, term structures, time-series statistics and Python.","design":"Empirical application","tags":["Cash-flow valuation","Fixed income \u0026 curves","Regression \u0026 inference"],"data_note":"GKK archive with verified style labels, matched curves and rights.","state":"description","href":"topic.html?id=A06.02.02"},{"id":"A06.03.01","title":"Equity Yield Slopes and the Sensitivity of Equity Portfolios to Interest Rates","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"conditional","question":"Do portfolio-level model-implied equity yield slopes predict differential subsequent exposure to government yield changes, and does the association survive controls for investment style and market exposure?","motivation":"Rate sensitivity may depend on the timing of priced dividends and on equity valuation states. An interaction design tests this association without claiming that an observed rate movement is an exogenous discount-rate shock.","prereq":"Asset pricing, fixed income, panel econometrics, Python.","design":"Empirical application","tags":["Cash-flow valuation","Fixed income \u0026 curves","Regression \u0026 inference","Time-series forecasting"],"data_note":"GKK archive and exact style-return matching (at least four styles).","state":"description","href":"topic.html?id=A06.03.01"},{"id":"A06.03.02","title":"Growth versus Value: Cash Flow Timing and Discount Rate Risk","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"not_required","question":"How much greater is discount-rate sensitivity for stylized growth than value claims, and is that prediction consistent with descriptive portfolio evidence?","motivation":"Cash-flow timing produces a transparent difference in discount-rate exposure even when two claims have identical initial market value. An offsetting dividend revision separates a mechanical duration effect from a return response.","prereq":"Discounted cash flow, duration, numerical derivatives, regression for optional evidence.","design":"Simulation","tags":["Cash-flow valuation","Fixed income \u0026 curves","Equilibrium \u0026 preferences"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A06.03.02"},{"id":"A06.04.01","title":"Equity and Bond Yield Slopes over the Business Cycle","area":"Asset Pricing","family":"F10","difficulty":2,"gate":"conditional","question":"How do matched-maturity equity and nominal Treasury yield slopes covary across the US business cycle, and is the relation stable across alternative measures of economic conditions?","motivation":"Equity and Treasury yield slopes summarize different claims on future states. Their co-movement over the business cycle is informative about valuation dynamics but does not identify a common structural shock.","prereq":"Asset pricing, term structure, regression and macro data.","design":"Empirical application","tags":["Cash-flow valuation","Fixed income \u0026 curves","Regression \u0026 inference","Time-series forecasting"],"data_note":"GKK archive and matching bond/macro time series.","state":"description","href":"topic.html?id=A06.04.01"},{"id":"A06.04.02","title":"Cash Flow News and Discount Rate News in Aggregate Stock Returns","area":"Asset Pricing","family":"F10","difficulty":3,"gate":"pending","question":"How much of unexpected aggregate equity return variation is associated with discount-rate versus cash-flow news under alternative parsimonious VAR information sets?","motivation":"Unexpected returns can reflect revisions in future cash flows or discount rates. A VAR provides one operational decomposition whose dependence on information and horizon is itself a research object.","prereq":"Asset valuation, VAR, matrix algebra, bootstrap and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Cash-flow valuation","Equilibrium \u0026 preferences"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A06.04.02"},{"id":"A07.01.01","title":"The Variance Risk Premium and the Predictability of Stock Market Returns","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"blocked","question":"Does an ex ante 30-day variance risk premium proxy help forecast US equity excess returns over 1 and 3 months relative to a historical mean, and how sensitive is the result to the physical variance forecast and sample coverage?","motivation":"An option-implied variance measure combines expected variation and compensation for variance risk. The difference between risk-neutral and physical forecasts may contain information about expected equity returns. The study must distinguish genuine ex ante variation from a difference constructed using future realized variance.","prereq":"Risk-neutral pricing, return and volatility measurement, predictive regressions, time-series forecasting, Python. Short historical coverage is a key supervision checkpoint.","design":"Empirical application","tags":["Time-series forecasting","Regression \u0026 inference","Tail risk \u0026 distributions"],"data_note":"An authorized SP500 price source with adequate history, or an explicitly approved redesign.","state":"description","href":"topic.html?id=A07.01.01"},{"id":"A07.01.02","title":"Variance Risk Premia and Economic Uncertainty","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Is a consistently measured 30-day variance-premium proxy associated with economic policy uncertainty beyond the level of expected physical variance and financial stress?","motivation":"Risk-neutral variance may rise because expected physical risk increases, because investors require more compensation for bearing risk, or both. This project asks whether a measured variance-premium proxy is associated with policy uncertainty after separating these channels statistically.","prereq":"Options and volatility, forecasting, HAC and data handling.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.01.02"},{"id":"A07.02.01","title":"Does Downside Beta Explain Cross-Sectional Stock Returns?","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Does downside beta help explain cross-sectional mean excess returns of public US equity portfolios after controlling for conventional market beta?","motivation":"Market beta summarizes linear exposure over all observations. Investors may also care about exposure in falling markets, but incremental downside beta can be noisy and highly correlated with conventional beta. The thesis tests whether predetermined downside exposure contributes to the cross-section of subsequent portfolio returns.","prereq":"Conditional moments, factor regressions, cross-sectional econometrics and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.02.01"},{"id":"A07.02.02","title":"Downside versus Upside Market Risk in Factor Investing","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Which equity factors have asymmetric market exposures and payoff distributions across down and up markets, and how stable is the asymmetry?","motivation":"Factor strategies can have different payoffs in rising and falling markets even when their unconditional market exposure is small. This project documents conditional payoffs and their stability; it does not attempt to infer a separate cross-sectional price of downside risk.","prereq":"Factor models, regression, bootstrap and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.02.02"},{"id":"A07.03.01","title":"Skewness Risk and the Cross-Section of Equity Returns","area":"Asset Pricing","family":"F03","difficulty":3,"gate":"pending","question":"Do lagged market coskewness exposures have incremental explanatory power for subsequent portfolio returns beyond standard market beta and factors?","motivation":"A linear market model ignores exposure to the square of market shocks. If marginal utility is sensitive to extreme aggregate outcomes, such nonlinear exposures may be relevant for expected returns. The empirical difficulty is estimating third-moment-related quantities reliably before observing the return to be explained.","prereq":"Factor pricing, regression, higher moments, bootstrap and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.03.01"},{"id":"A07.03.02","title":"Tail Dependence in Equity Portfolios and Factor Strategies","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Do US equity industry portfolios and factor strategies display excess lower-tail co-exceedance relative to Gaussian copulas with the same rank dependence?","motivation":"Two assets with the same ordinary correlation may have very different probabilities of jointly extreme losses. A copula comparison separates the marginal distributions from dependence and asks whether Gaussian dependence understates joint downside events at observable thresholds.","prereq":"Probability, rank statistics, likelihood, time-series bootstrap, Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.03.02"},{"id":"A07.04.01","title":"Volatility Risk Exposure and Expected Equity Portfolio Returns","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Are lagged exposures to aggregate volatility innovations associated with future average portfolio excess returns after accounting for market beta and standard factors?","motivation":"A portfolio that performs poorly when aggregate volatility rises may require compensation even after its market beta is accounted for. The project estimates exposure to unexpected volatility news and tests whether that predetermined exposure is related to future portfolio returns.","prereq":"Factor models, rolling regressions, Fama-MacBeth, time-series inference, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.04.01"},{"id":"A07.04.02","title":"Are Equity Factor Premia Compensation for Crash Risk?","area":"Asset Pricing","family":"F03","difficulty":2,"gate":"pending","question":"Do factor strategies with worse payoffs in market crashes earn higher average excess returns, and is the relation robust to ordinary market beta and sampling uncertainty?","motivation":"Risk compensation is often motivated by poor payoffs in states where marginal utility is high. Severe market downturns provide an imperfect empirical proxy for such states. This thesis asks whether a predetermined measure of crash exposure helps explain subsequent return differences, rather than interpreting same-sample crashes as proof of a premium.","prereq":"Factor pricing, tail measures, regression, bootstrap, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A07.04.02"},{"id":"A08.01.01","title":"Mean-Variance Optimization and the Cost of Estimation Error","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"How much does estimation error in expected returns and covariance reduce out-of-sample mean-variance portfolio performance relative to equal weights and minimum variance?","motivation":"Optimization amplifies estimation error into unstable allocations. A known-moment experiment separates the effects of mean and covariance estimation before historical evaluation.","prereq":"Portfolio theory, covariance estimation, convex optimization and Python SciPy/cvxpy.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs","Simulation \u0026 Monte Carlo"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.01.01"},{"id":"A08.01.02","title":"Covariance Shrinkage and Portfolio Performance","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Does Ledoit-Wolf covariance shrinkage improve out-of-sample global minimum-variance portfolio risk and turnover relative to sample covariance and equal weighting, and how does performance depend on estimation-window length?","motivation":"GMV avoids noisy means but can still amplify covariance noise. Shrinkage trades bias for stability and should be judged on subsequent returns.","prereq":"Matrix algebra, covariance estimation, optimization, portfolio return arithmetic, Python/SciPy/scikit-learn. No stock-level histories needed.","design":"Empirical application","tags":["Calibration \u0026 estimation","Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.01.02"},{"id":"A08.02.01","title":"Black-Litterman Portfolio Choice under Uncertain Expected Returns","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"How do prior strength and uncertainty in relative-return views affect Black-Litterman posterior allocations and their held-out economic performance?","motivation":"Portfolio choice based on estimated expected returns is vulnerable to sampling error. Black-Litterman uses a reference portfolio and noisy relative-return views to regularize estimates of the mean. Its economic value depends on whether those views improve held-out allocation decisions after constraints and costs. The project distinguishes a genuine sensitivity to prior uncertainty from a parameter that cancels by construction.","prereq":"Multivariate normal distributions, portfolio optimization, matrix algebra and Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.02.01"},{"id":"A08.02.02","title":"Robust Portfolio Optimization under Parameter Uncertainty","area":"Asset Pricing","family":"F12","difficulty":3,"gate":"pending","question":"Can uncertainty-set portfolio optimization improve realized utility and stability relative to plug-in mean-variance portfolios without excessive conservatism?","motivation":"Mean ambiguity penalizes exposure to poorly estimated expected returns. Robust utility and actual economic value need not rank policies the same way.","prereq":"Portfolio theory, convex optimization, statistics and Python/CVXPY.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.02.02"},{"id":"A08.03.01","title":"Risk Parity versus Minimum-Variance Portfolios","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Does equal risk contribution deliver more stable risk allocation than minimum variance, and at what cost in realized volatility and turnover?","motivation":"Risk parity allocates component risk rather than capital, potentially balancing exposures without mechanically minimizing total variance.","prereq":"Linear algebra, convex optimization, portfolio theory, returns.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.03.01"},{"id":"A08.03.02","title":"Volatility Targeting in Equity Portfolio Management","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Does past-only volatility targeting improve risk-adjusted performance and drawdowns versus static equity allocations after matching ex-ante risk and charging realistic costs?","motivation":"Volatility targeting adjusts market exposure using estimated risk. Its value depends on cash financing, lagged information, trading costs and ex-ante benchmark matching.","prereq":"Portfolio theory, volatility estimation, Python and backtest discipline.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Portfolio optimization","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.03.02"},{"id":"A08.04.01","title":"Portfolio Choice under Expected Shortfall Constraints","area":"Asset Pricing","family":"F12","difficulty":3,"gate":"pending","question":"Do expected-shortfall-constrained allocations improve held-out downside risk and economic performance relative to variance-constrained and equal-weight portfolios?","motivation":"Expected shortfall targets adverse outcomes rather than penalizing upside and downside alike. Its benefits depend on scenario quality and feasible training risk budgets.","prereq":"Convex optimization, portfolio theory, risk measures, Python/SciPy.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs","Tail risk \u0026 distributions","Simulation \u0026 Monte Carlo"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.04.01"},{"id":"A08.04.02","title":"Dynamic versus Static Stock-Bond Asset Allocation","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Does a long-only dynamic stock-bond allocation driven by past covariance estimates improve net risk-adjusted performance relative to static 60/40 and expanding-risk benchmarks?","motivation":"Dynamic stock-bond allocation can exploit changing covariance, but comparison requires valid holding returns and equal trading conventions.","prereq":"Portfolio theory, covariance estimation, fixed income, time series.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A08.04.02"},{"id":"A09.01.01","title":"Global versus Regional Equity Factor Models","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"pending","question":"Do developed-market factors price regional equity portfolios as effectively as regional factors? Is the incremental explanatory or pricing power of local factors stable across regions and sample periods?","motivation":"Investors can hold portfolios across developed equity markets, but global factor exposures need not explain local average returns equally well. Comparing global and local models on identical test assets isolates differences in empirical pricing performance without equating those differences with market segmentation.","prereq":"CAPM, FF factors, multivariate OLS, hypothesis testing and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Calibration \u0026 estimation"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A09.01.01"},{"id":"A09.01.02","title":"International Diversification and Time-Varying Market Integration","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"pending","question":"How have correlations, common-factor exposures and the realized diversification benefits of nonoverlapping developed equity regions changed over time and across volatility regimes?","motivation":"International equity diversification can weaken precisely when global volatility rises. Separate changes in realized co-movement from changes in portfolio risk and from stronger claims about integration of financial markets.","prereq":"Portfolio theory, factor regressions, PCA, time-series inference and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A09.01.02"},{"id":"A09.02.01","title":"The Forward Premium Puzzle and Currency Carry","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"conditional","question":"Does the observed forward premium forecast subsequent spot appreciation as UIP implies, and how does this bilateral evidence relate to published currency carry returns?","motivation":"The forward premium puzzle concerns the relationship between observed bilateral forward prices and subsequent exchange-rate changes. A published cross-sectional carry factor is a different object: it combines currencies and portfolio formation rules. Keep these two sources of evidence separate.","prereq":"International finance, exchange-rate conventions, predictive regression and Python.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF"],"data_note":"Observed BoE forward series and matching G10 carry workbook; coverage and rights.","state":"description","href":"topic.html?id=A09.02.01"},{"id":"A09.02.02","title":"Currency Carry Returns and Global Risk States","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"conditional","question":"Are currency carry returns lower and market exposures larger in risk-off states, and can lagged global risk measures forecast carry returns?","motivation":"Currency carry earns a payoff by holding currencies with higher interest-rate-related carry against lower carry currencies. Its exposure to global risk-off states may be important even if its unconditional average payoff is positive. Distinguish a contemporaneous risk-state description from a forecast made before the return period.","prereq":"FX returns, conditional regressions, portfolio factors, time-series inference.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"G10 carry workbook, VIX and NFCI with authorized use and aligned dates.","state":"description","href":"topic.html?id=A09.02.02"},{"id":"A09.03.01","title":"Value and Momentum Everywhere: Common Risk or Diversification?","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"pending","question":"How much of cross-asset value and momentum variation is explained by common style factors, and does combining the two styles reduce portfolio risk beyond diversification within either style alone?","motivation":"Value and momentum appear in several asset classes, but published factor portfolios may share common risks despite different underlying assets. The original paper's factor data allow a focused study of dependence and diversification without pretending to reconstruct security-level positions.","prereq":"Factor investing, covariance matrices, PCA, portfolio mathematics and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A09.03.01"},{"id":"A09.03.02","title":"Carry as a Cross-Asset Investment Factor","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"conditional","question":"How much common risk is present in published cross-asset carry returns, and does combining the asset-class sleeves reduce downside risk during stress?","motivation":"Carry signals differ across bonds, commodities, currencies and other asset classes. A diversified carry composite can reveal whether these sleeves share risk-off exposure, but comparisons depend on the original strategy leverage and return conventions.","prereq":"Multi-asset pricing, portfolio statistics, PCA and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization","Tail risk \u0026 distributions"],"data_note":"Original carry strategy workbook, sleeve definitions, permissions and common sample.","state":"description","href":"topic.html?id=A09.03.02"},{"id":"A09.04.01","title":"Time-Series Momentum across Asset Classes","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"pending","question":"How diversified are time-series momentum payoffs across asset classes, and how do their market exposures and conditional performance vary in adverse equity market states?","motivation":"Trend-following strategies across asset classes can diversify equity exposure, but their published returns often already incorporate volatility scaling. Study how sleeve allocation changes realized risk and stress behavior without claiming a new futures-level replication.","prereq":"Portfolio theory, futures fundamentals, regression and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Portfolio optimization","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A09.04.01"},{"id":"A09.04.02","title":"Digital Assets and Traditional Asset Pricing Factors","area":"Asset Pricing","family":"F07","difficulty":2,"gate":"blocked","question":"How stable is Bitcoin's exposure to conventional equity factors and lagged stress conditions, and how much does time aggregation affect this inference?","motivation":"Bitcoin trades through weekends and around the clock, unlike the equity portfolios used to construct conventional factors. Apparent changes in market exposure may depend on asynchronous month-end measurement as well as economic integration. Authorized and correctly timed input data are essential.","prereq":"Return construction, factor models, regression, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Tail risk \u0026 distributions"],"data_note":"Authorized Bitcoin price series, plus matching factor/VIX files.","state":"description","href":"topic.html?id=A09.04.02"},{"id":"A10.01.01","title":"Regularized Regressions for Equity Premium Forecasting","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do ridge, LASSO or elastic-net regressions improve one-month equity premium forecasts relative to the historical mean and ordinary least squares? Are improvements robust to tuning and evaluation windows?","motivation":"Many correlated predictors make OLS unstable when the historical sample is short. Penalization exchanges bias for lower estimation variance; its benefit must be measured after counting the cost of tuning, not with a penalty selected on the test set.","prereq":"OLS, matrix algebra, basic regularization, scikit-learn pipelines, time-series evaluation.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Machine learning"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.01.01"},{"id":"A10.01.02","title":"Predicting Factor Returns with Machine Learning","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do ridge and LASSO forecasts of monthly SMB, HML and momentum improve over factor-specific historical means and fixed OLS models in a genuinely held-out period?","motivation":"Factor premia may vary with macro-financial state and their own lagged performance. The question is whether regularized forecasts generalize across distinct factor payoffs, not whether a selected winning factor is predictable.","prereq":"Factor models, regression, regularization, time-series validation and Python (scikit-learn).","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF","Machine learning"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.01.02"},{"id":"A10.02.01","title":"Tree-Based Models for Stock Market Return Predictability","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"Do shallow tree ensembles provide incremental out-of-sample equity-premium forecast accuracy relative to linear models under identical information and model-selection rules?","motivation":"Shallow ensembles can capture thresholds and interactions, but financial time series contain few independent observations. The fair test gives nonlinear and linear models the same information and honest selection budget.","prereq":"Time series, basic ML, Python/scikit-learn and return arithmetic.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Machine learning"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.02.01"},{"id":"A10.02.02","title":"Neural Networks versus Linear Models in Financial Forecasting","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"Can a deliberately small neural network improve next-month portfolio return forecasts over linear models under date-blocked validation?","motivation":"Pooling portfolios can improve effective training information, but observations in a given month share shocks. Random row splits leak common time information, and a large network may mistake cross-sectional dependence for independent evidence.","prereq":"Regression, basic ML, Python scikit-learn, temporal validation.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Machine learning"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.02.02"},{"id":"A10.03.01","title":"Nonlinear Latent Factors and Cross-Sectional Pricing Errors","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"Can a characteristic-conditioned nonlinear exposure map reduce held-out portfolio pricing errors relative to PCA and a linear conditional factor model at the same latent dimension?","motivation":"Explaining return variance is not equivalent to pricing average returns. A characteristic-dependent factor loading can improve cross-sectional generalization, but flexible maps may fit noise or exploit test assets when constructing factors.","prereq":"Factor pricing, PCA, regression, basic neural networks, Python/PyTorch or sklearn.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Machine learning","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.03.01"},{"id":"A10.03.02","title":"Sparse Predictors and the Factor Zoo","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"conditional","question":"Do sparse factor selections learned on one set of test assets and historical dates reduce pricing errors for different assets on future dates relative to FF3/FF5 and dense shrinkage?","motivation":"A large zoo of proposed factors creates a high-dimensional pricing problem. Sparse selection can reduce redundancy but may be unstable; the decisive distinction is performance on new dates for known assets versus new dates and different assets. Data rights and exact factor definitions are binding.","prereq":"Linear algebra, regularization, SDF moments, Python.","design":"Empirical application","tags":["Constrained optimization","Regression \u0026 inference","Factor models \u0026 SDF","Machine learning"],"data_note":"Specific OSAP release, dictionary, data rights and coverage.","state":"description","href":"topic.html?id=A10.03.02"},{"id":"A10.04.01","title":"Interpretable Machine Learning for Financial Risk Forecasts","area":"Asset Pricing","family":"F09","difficulty":2,"gate":"pending","question":"Do interpretable nonlinear forecasts of market variance improve on linear/HAR benchmarks, and are their feature attributions stable across periods?","motivation":"Nonlinear variance forecasts can capture interactions between recent volatility and financial conditions, but interpretation can be unstable with correlated inputs. The thesis asks jointly about forecast quality and stability of attributions, not causality.","prereq":"Regression, tree models, time-series validation, Python and visualization.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Machine learning","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.04.01"},{"id":"A10.04.02","title":"Backtest Overfitting and the Illusion of Predictability","area":"Asset Pricing","family":"F09","difficulty":3,"gate":"pending","question":"How does the number of candidate predictive models affect apparent OOS performance under a no-predictability null, and how much does nested temporal validation reduce the gap between reported and independent test performance?","motivation":"The best-looking backtest from many candidates can appear profitable even under no predictability. The experiment separates legitimate model selection on past validation data from invalid repeated selection on final outcomes.","prereq":"Predictive regressions, Monte Carlo, time-series dependence, Python and basic multiple testing.","design":"Empirical application","tags":["Simulation \u0026 Monte Carlo","Regression \u0026 inference","Time-series forecasting","Machine learning"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A10.04.02"},{"id":"A11.01.01","title":"The Stochastic Discount Factor and the Geometry of Risk Premia","area":"Asset Pricing","family":"F08","difficulty":1,"gate":"not_required","question":"How do the payoff span and market incompleteness determine the minimum-norm SDF, the attainable Sharpe ratio and the set of admissible positive pricing kernels?","motivation":"Asset prices identify the component of the stochastic discount factor (SDF) that lies in the span of traded payoffs, but they generally do not identify the entire SDF in incomplete markets. This distinction is economically important: a pricing kernel that exactly matches traded prices need not be unique or even nonnegative. The project uses finite-state economies to connect this identification problem to portfolio efficiency, the Sharpe ratio and no-arbitrage restrictions. Its main contribution is to establish these relationships exactly, rather than to estimate a structural consumption model.","prereq":"Linear algebra, probability, asset pricing and convex optimization in Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization","Factor models \u0026 SDF","Portfolio optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A11.01.01"},{"id":"A11.01.02","title":"From Factor Betas to Stochastic Discount Factors","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"When do beta-pricing and linear SDF estimators produce identical pricing errors, and how do weighting and traded-factor restrictions change the conclusions on common test assets?","motivation":"Beta pricing and a linear stochastic discount factor are often presented as different empirical approaches. Under a common normalization and weighting matrix they can be two parameterizations of the same restrictions. Differences in estimates may instead reflect constraints, weights or the treatment of traded factors.","prereq":"Asset pricing, linear algebra, covariance estimation, regression and basic GMM.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.01.02"},{"id":"A11.02.01","title":"The Hansen-Jagannathan Bound and the Volatility of the Pricing Kernel","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"How does the minimum SDF volatility implied by US portfolio returns increase as test assets are added, and can a calibrated consumption-based SDF plausibly satisfy the resulting restrictions?","motivation":"The Hansen–Jagannathan volatility bound quantifies how variable a pricing kernel must be to price a set of traded excess payoffs. Adding assets can tighten the restriction, but the sample bound also becomes more vulnerable to covariance estimation error. Consumption growth provides an economic benchmark rather than a guaranteed pricing model.","prereq":"SDF theory, covariance and matrix inversion, portfolio theory, elementary bootstrap and Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Factor models \u0026 SDF","Equilibrium \u0026 preferences","Portfolio optimization"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.02.01"},{"id":"A11.02.02","title":"Hansen-Jagannathan Distance and the Comparison of Asset Pricing Models","area":"Asset Pricing","family":"F08","difficulty":3,"gate":"pending","question":"How do CAPM, FF3 and FF5 linear discount factors compare using Hansen-Jagannathan pricing-error distance on common test assets and independent evaluation periods?","motivation":"A misspecified pricing model can be compared to others by asking how much its discount factor would have to change to price the same payoff span. The Hansen–Jagannathan distance answers this question in an unrestricted quadratic metric. It is not the volatility bound and does not certify positivity.","prereq":"SDF, factor models, matrix algebra, GMM basics and Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Constrained optimization","Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.02.02"},{"id":"A11.03.01","title":"Testing Euler Equations with Generalized Method of Moments","area":"Asset Pricing","family":"F08","difficulty":3,"gate":"pending","question":"How sensitive are estimated CRRA preference parameters and Euler pricing errors to the selection of test assets, conditioning instruments and GMM weighting matrices? Do weakly informative moments explain instability?","motivation":"Consumption Euler equations can be weakly informative about preference parameters even when a numerical optimizer converges. Moment selection, weighting and identification are therefore part of the economic question, rather than nuisance implementation details.","prereq":"CRRA utility and SDFs, nonlinear optimization, GMM/HAC, matrix algebra and Python SciPy/statsmodels.","design":"Empirical application","tags":["Calibration \u0026 estimation","Constrained optimization","Regression \u0026 inference","Factor models \u0026 SDF","Equilibrium \u0026 preferences"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.03.01"},{"id":"A11.03.02","title":"Conditional versus Unconditional Asset Pricing Restrictions","area":"Asset Pricing","family":"F08","difficulty":3,"gate":"pending","question":"Do predetermined valuation and interest-rate instruments reveal conditional pricing errors that an unconditional factor SDF hides?","motivation":"A model may price average returns while failing to price returns conditional on information known when portfolios are formed. Managed payoffs make these conditional restrictions testable, provided instrument timing and the kernel normalization are explicit.","prereq":"SDF, linear factors, GMM, HAC and matrix algebra.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.03.02"},{"id":"A11.04.01","title":"Excess Volatility and the Present-Value Model of Equity Prices","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"pending","question":"How robust is the apparent excess variability of real equity prices relative to a constant-discount ex post dividend benchmark to detrending, horizon and terminal-value choices?","motivation":"Equity prices may look too volatile relative to a constant-discount dividend benchmark. A valid comparison requires consistent real units, a fixed horizon, a terminal convention and a stationary or consistently scaled object. Finite-sample variance differences alone cannot establish excess volatility.","prereq":"Asset pricing, conditional expectation, time-series stationarity, simulation.","design":"Empirical application","tags":["Cash-flow valuation","Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A11.04.01"},{"id":"A11.04.02","title":"Return Predictability and the Joint-Hypothesis Problem","area":"Asset Pricing","family":"F08","difficulty":2,"gate":"not_required","question":"Can identical predictive return moments arise under a valid time-varying-risk-premium SDF and a behavioral price-distortion interpretation, and what extra restrictions would distinguish them?","motivation":"Predictability can coexist with a positive stochastic discount factor that prices all modeled payoffs. A misspecified constant kernel can fail on the same return history. Identical predictive moments thus cannot distinguish a risk-premium mechanism from a reduced-form distortion without auxiliary economic restrictions.","prereq":"Conditional expectation, Markov chains, asset pricing, regression.","design":"Simulation","tags":["Simulation \u0026 Monte Carlo","Regression \u0026 inference","Factor models \u0026 SDF","Equilibrium \u0026 preferences"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A11.04.02"},{"id":"A12.01.01","title":"Liquidity-Related Anomalies and Factor Pricing","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"conditional","question":"Are published liquidity-related long-short returns explained by standard factors, and do their residual returns vary with financial conditions?","motivation":"Liquidity-related spreads may reflect risk or correlated characteristics. Factor regressions and financial-condition interactions measure residual associations, not structural liquidity causation.","prereq":"Factor models, regression/HAC, panel of portfolio returns, Python parquet support.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Matching OSAP revision, liquidity signal definitions and factor/NFCI coverage.","state":"description","href":"topic.html?id=A12.01.01"},{"id":"A12.01.02","title":"Funding Constraints and the Performance of Low-Beta Strategies","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Are US BAB returns lower when financial conditions tighten, and do lagged financial conditions predict subsequent BAB returns after controlling for standard factors?","motivation":"Funding conditions may covary with betting-against-beta returns without establishing a structural borrowing-constraint channel.","prereq":"CAPM, multifactor regressions, funding liquidity economics, time-series HAC and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A12.01.02"},{"id":"A12.02.01","title":"Investor Confidence and Expected Stock Market Returns","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"conditional","question":"Do lagged changes in individual and institutional one-year confidence predict subsequent market excess returns beyond valuation ratios?","motivation":"Survey confidence may add predictive information beyond valuation ratios. Confidence changes are not structural innovations and raw and smoothed series cannot be interchanged.","prereq":"Predictive regressions, survey measurement, HAC, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Authorized Yale monthly confidence series and original release dates.","state":"description","href":"topic.html?id=A12.02.01"},{"id":"A12.02.02","title":"Sentiment and the Cross-Section of Anomaly Returns","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"conditional","question":"Do preselected equity anomaly portfolios earn different subsequent factor-adjusted returns in high versus low Baker-Wurgler sentiment states?","motivation":"Sentiment may be associated with different subsequent anomaly returns. Prespecified published spreads test state-dependent residual performance without mining stock-level strategies.","prereq":"Factor regressions, bootstrap, financial econometrics, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Factor models \u0026 SDF"],"data_note":"Matching OSAP and Baker–Wurgler sentiment releases and coverage.","state":"description","href":"topic.html?id=A12.02.02"},{"id":"A12.03.01","title":"Momentum and Long-Term Reversal: Competing Return Patterns","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"pending","question":"Do published portfolios sorted on past returns show systematically different average spreads and factor-adjusted returns across formation windows, and how stable are the differences across market regimes?","motivation":"Momentum and reversal reflect different formation horizons; published spreads differ in orientation, not necessarily holding horizon.","prereq":"Factor models, portfolio returns, OLS/HAC and Python data handling.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=A12.03.01"},{"id":"A12.03.02","title":"The Disposition Effect and Return Predictability: A Simulation Study","area":"Asset Pricing","family":"F12","difficulty":3,"gate":"not_required","question":"Can asymmetric selling relative to investors' purchase reference prices produce short-run underreaction or subsequent return reversals in a stylized market with identical fundamental news?","motivation":"Reference-dependent selling may generate asymmetric supply following news. A stylized clearing market isolates the mechanism without claiming a preference equilibrium.","prereq":"Behavioral finance, probability, numerical root finding, simulation and basic regression.","design":"Simulation","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Regression \u0026 inference"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A12.03.02"},{"id":"A12.04.01","title":"Limits to Arbitrage and the Persistence of Mispricing","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"not_required","question":"How do wealth or position constraints and noise persistence affect the magnitude and persistence of mispricing in a stylized finite-horizon market?","motivation":"Noise demand and predetermined position caps sustain deviations before liquidation. The model separates limits and interim risk without asserting an endogenous funding equilibrium.","prereq":"Microeconomic market clearing, asset pricing, probability and Python.","design":"Simulation","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Regression \u0026 inference","Equilibrium \u0026 preferences"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=A12.04.01"},{"id":"A12.04.02","title":"Transaction Costs and the Economic Viability of Published Anomalies","area":"Asset Pricing","family":"F12","difficulty":2,"gate":"conditional","question":"For a preselected set of published anomalies, what combinations of turnover and per-dollar trading costs eliminate gross mean returns or factor-adjusted alpha?","motivation":"Gross anomaly returns do not establish tradability. Scenario analysis quantifies the cost and turnover combinations that absorb published returns or alpha.","prereq":"Factor models, portfolio accounting, regression, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Factor models \u0026 SDF","Hedging \u0026 trading costs"],"data_note":"OSAP and signal metadata; turnover requires separate verification.","state":"description","href":"topic.html?id=A12.04.02"},{"id":"D01.01.01","title":"The Black-Scholes Model and the Economic Implications of Its Assumptions","area":"Derivatives","family":"F01","difficulty":1,"gate":"not_required","question":"How do volatility, interest rates, dividends and time to maturity change European option prices and Greeks? How large are the pricing differences when the lognormal assumption is relaxed while matching forward and terminal variance?","motivation":"The Black–Scholes price is an equilibrium restriction in a frictionless diffusion economy, not a general description of the option market. Its Greeks quantify local exposures to model inputs; they need not predict the effect of a large change in those inputs. A second issue is whether two terminal distributions with the same forward and stock-price variance imply the same price. This project separates these two questions: comparative statics within the model and valuation across alternative terminal laws.","prereq":"Probability, basic stochastic calculus, derivatives pricing and Python NumPy/SciPy. No external quotes required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.01.01"},{"id":"D01.01.02","title":"Option Pricing under Model Misspecification: Implications for Prices and Hedging","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"How does fitting Black-Scholes to an at-the-money jump-diffusion price affect held-out option pricing and delta hedging across strikes and jump intensities?","motivation":"A model can match one liquid quote while assigning different risks to other strikes. In a jump-diffusion market, a stock position hedges infinitesimal price changes but cannot generally offset a finite jump. This study asks whether an ATM-calibrated diffusion gives useful prices and hedge positions away from its calibration contract, and isolates the role of discrete rebalancing from residual jump exposure.","prereq":"Risk-neutral valuation, BSM, Poisson processes, stochastic calculus and Python simulation.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.01.02"},{"id":"D01.01.03","title":"The Impact of Non-Normal Returns on European Option Pricing","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"How do risk-neutral skewness and excess kurtosis change European option prices and implied volatility smiles when forward and log variance are matched?","motivation":"Vanilla options reveal distributional information beyond mean and variance because their payoffs are nonlinear. A controlled terminal-distribution experiment can isolate how asymmetry and tail thickness affect the smile without confounding the comparison with a different forward or log-return variance. The task is not to recover a unique distribution from its first four moments.","prereq":"Probability, lognormal pricing, numerical root finding and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.01.03"},{"id":"D01.02.01","title":"Option Pricing under Stochastic Volatility: The Heston Model","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"When does stochastic volatility improve pricing beyond constant volatility, and which dimensions of a cross-section of European options identify its parameters? Assess the hypothesis that strike and maturity coverage jointly improve held-out pricing, even when parameter recovery remains weak.","motivation":"A stochastic-volatility model adds economically meaningful degrees of freedom, but a low pricing residual does not establish that the corresponding parameters are precisely identified. Strike coverage informs asymmetry and curvature; maturity coverage informs the variance dynamics. The project studies whether additional information improves held-out valuation even when the parameter estimates themselves remain imprecise.","prereq":"Risk-neutral pricing, Ito calculus, numerical integration, nonlinear optimization, Python/NumPy/SciPy. The characteristic-function derivation is the advanced element; use a published formula if needed and explain its logic.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier","Calibration \u0026 estimation","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.02.01"},{"id":"D01.02.02","title":"Stochastic Volatility and the Economic Determinants of the Implied Volatility Smile","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"Which Heston parameters control distinct smile features, and when do their effects become difficult to distinguish?","motivation":"The level, skew and curvature of the implied volatility smile are often associated with different stochastic-volatility parameters. These associations depend on maturity and the baseline parameter vector: multiple perturbations may produce almost indistinguishable smiles. This study uses controlled Heston comparative statics rather than estimating a model from market quotes.","prereq":"Stochastic calculus, option pricing, numerical integration and linear algebra.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.02.02"},{"id":"D01.02.03","title":"Comparing Local and Stochastic Volatility Models: Pricing and Hedging Performance","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"When a local-volatility model reproduces a Heston-generated vanilla surface, how different are barrier prices and delta hedges in the Heston data-generating market?","motivation":"Two models can reproduce the same vanilla option surface yet disagree on the law of the underlying path. Local volatility encodes the one-dimensional risk-neutral marginals; stochastic volatility retains a latent variance state. Barrier options and hedging provide a way to assess the economic relevance of this distinction while controlling the quality of the vanilla fit.","prereq":"Ito calculus, Heston, PDE/Monte Carlo, surface differentiation; advanced Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.02.03"},{"id":"D01.03.01","title":"Jump Risk and the Pricing of Equity Options","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"How do jump intensity, mean jump size and jump dispersion affect equity option prices and implied-volatility skew at a fixed total instantaneous log-return variance?","motivation":"A diffusion with rare jumps and a Gaussian diffusion can have equal instantaneous log-return variance but very different short-maturity tail probabilities. Holding total variance fixed isolates the price implications of discontinuity rather than simply increasing the overall level of risk. The project studies how intensity, jump asymmetry and jump dispersion reshape the risk-neutral smile.","prereq":"BSM, Poisson processes, numerical integration, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.03.01"},{"id":"D01.03.02","title":"Stochastic Volatility versus Jump Risk: Explaining the Implied Volatility Skew","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"Can Heston and Merton models fit the same noisy synthetic vanilla quotes, and which maturity and strike diagnostics discriminate between the two mechanisms?","motivation":"Negative equity option skew can arise from diffusive leverage or from discontinuous returns. A fit to a restricted set of quotes may not distinguish these mechanisms. This project compares two competing risk-neutral models against known synthetic truth, using held-out maturity and strike information to assess their discriminatory power.","prereq":"Stochastic calculus, characteristic functions, optimization, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier","Calibration \u0026 estimation","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.03.02"},{"id":"D01.03.03","title":"Option Pricing and Hedging in the Presence of Extreme Market Movements","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"How sensitive are hedge losses to rare market gaps, and how much can a second traded vanilla option reduce jump-related tail risk at the same initial capital?","motivation":"When returns jump, a delta hedge is exposed to a finite-price residual rather than only a local diffusion error. A second option may reduce this exposure but introduces financing, sensitivity and position-size constraints. This study evaluates the benefit in tail losses using a common initial premium and common physical scenarios, rather than comparing strategies that start with different capital.","prereq":"Option Greeks, jump diffusion, portfolio accounting, Monte Carlo, ES.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.03.03"},{"id":"D01.04.01","title":"Option Pricing with Levy Processes: Beyond Gaussian Returns","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"Can variance-gamma and finite-activity jump models with comparable variance reproduce different strike and maturity patterns, and which pricing properties are robust to tail and discretization choices?","motivation":"In the Black–Scholes model, the same volatility parameter prices European options of all strikes and maturities. Exponential Lévy models relax Gaussianity while retaining independent, stationary increments. A comparison at a common forward and log-return variance isolates differences in higher cumulants and their consequences for the option smile. The aim is not to fit market quotes, but to establish what different jump mechanisms imply for prices and for numerical accuracy in a controlled experiment.","prereq":"Characteristic functions, stochastic processes, option pricing, quadrature.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.04.01"},{"id":"D01.04.02","title":"Rough Volatility and the Short-Term Behavior of Option Prices","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"How does the roughness parameter alter the scaling of near-ATM skew as maturity decreases, and can the predicted distinction be measured reliably with numerical prices?","motivation":"Short-dated option skew can be steep even when the expected variance curve is smooth. Rough volatility changes the sensitivity of instantaneous variance to recent innovations. The scientific challenge is to separate the predicted short-time scaling from the numerical error in pricing options at very short expiries.","prereq":"Gaussian processes, stochastic calculus, option pricing, MC and numerical linear algebra.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.04.02"},{"id":"D01.04.03","title":"Model Complexity versus Pricing Accuracy in Modern Option Pricing","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"When is added pricing-model complexity justified by held-out surface accuracy, parameter stability and computational cost rather than in-sample fit alone?","motivation":"Additional parameters reduce an in-sample pricing objective only when they provide flexibility in the relevant directions. They can also increase numerical cost and estimation uncertainty. This project evaluates model complexity through three distinct outcomes: held-out price accuracy, stability of parameters and computation time, rather than treating the best fit as the best model.","prereq":"Derivative pricing, numerical integration, constrained optimization, statistics.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier","Calibration \u0026 estimation","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D01.04.03"},{"id":"D02.01.01","title":"The Information Content of the Equity Index Volatility Skew","area":"Derivatives","family":"F01","difficulty":2,"gate":"blocked","question":"Does a consistently defined equity index option-skew measure improve forecasts of downside equity returns beyond the VIX?","motivation":"Option-implied skew and variance describe different aspects of the risk-neutral return distribution. The empirical question is whether the skew statistic adds information about physical downside events beyond the level of implied volatility. Risk-neutral asymmetry is not itself a probability forecast, and a historical series can change meaning when the provider revises its methodology.","prereq":"Option pricing, logistic regression, probability, time-series validation and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Authorized SKEW vintage, final methodology, common sample and downside event counts.","state":"description","href":"topic.html?id=D02.01.01"},{"id":"D02.01.02","title":"The Term Structure of Implied Volatility in Equity Markets","area":"Derivatives","family":"F01","difficulty":2,"gate":"pending","question":"Does the slope of the VIX and three-month implied variance curve improve forecasts of subsequent realized market variance relative to the VIX alone and a historical-variance benchmark?","motivation":"An implied-volatility term structure combines expectations of future variance with compensation for bearing variance risk. Comparing a short index with a longer-horizon index may reveal useful information about the timing of risk, but the option-implied variance is a risk-neutral quantity and the forecast target is a physical realized variance proxy.","prereq":"Volatility measures, OLS, time-series forecasting and pandas/statsmodels. No option chains required.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D02.01.02"},{"id":"D02.02.01","title":"SVI versus SABR: A Comparative Study of Implied Volatility Surface Fitting","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"Which of raw SVI and lognormal SABR provides more stable and accurate smile estimates when quotes are sparse or noisy? Does the ranking change with maturity, asymmetry and the loss function?","motivation":"A flexible parametric smile can interpolate liquid strikes yet behave poorly where quotes are sparse. SVI and SABR encode shape differently and can be compared under the same quote information and noise. The goal is to evaluate the fit–stability trade-off rather than claim that either raw slice parameterization produces a globally arbitrage-free surface.","prereq":"Black pricing, stochastic calculus, numerical optimization and Python SciPy. Familiarity with Heston characteristic functions helpful; no option database required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D02.02.01"},{"id":"D02.02.02","title":"Calibrating Equity Option Surfaces with Real Market Quotes","area":"Derivatives","family":"F01","difficulty":3,"gate":"blocked","question":"How sensitive are SVI and Heston calibration and interpolation to quote cleaning, error weighting and held-out market prices on the same underlying?","motivation":"Calibration results from actual option quotes depend on the economic model and on how the quotes are selected, aligned and weighted. A study of market prices must separate market microstructure and measurement choices from model differences. This proposal compares slice-based and structural models only after a genuinely usable, authorized quote panel has been established.","prereq":"Options, IV inversion, nonlinear optimization, data engineering; licensed data access mandatory.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Constrained optimization"],"data_note":"Licensed option quotes with at least 10 dates, settlement and synchronized forwards.","state":"description","href":"topic.html?id=D02.02.02"},{"id":"D02.03.01","title":"Arbitrage-Free Interpolation of Implied Volatility Smiles","area":"Derivatives","family":"F01","difficulty":2,"gate":"not_required","question":"Which interpolation method balances fidelity to sparse and noisy quotes, accuracy at unobserved strikes and the absence of butterfly arbitrage? What is the cost of imposing no-arbitrage restrictions?","motivation":"An implied-volatility smile can appear smooth while implying a negative butterfly price. With sparse noisy quotes, forcing price convexity changes the fit, and the trade-off is measurable against an independently generated clean surface. This project focuses on a single expiry and on the economic meaning of finite-grid restrictions, not on global extrapolation.","prereq":"Black-Scholes inversion, convexity, elementary linear/quadratic programming, SciPy or CVXPY.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D02.03.01"},{"id":"D02.03.02","title":"Calendar-Spread Arbitrage and the Construction of Volatility Surfaces","area":"Derivatives","family":"F01","difficulty":3,"gate":"not_required","question":"What fit and stability costs arise from enforcing calendar and strike no-arbitrage restrictions on noisy multi-expiry option quotes?","motivation":"Implied-volatility surfaces are typically fitted to separate expiries, although their option prices must also be consistent through time. Noisy quotes can violate both butterfly and calendar restrictions. Joint price constraints can improve consistency at the expense of fit; the study measures that cost and tests whether it improves recovery of the clean generating surface.","prereq":"BSM and implied volatility, convexity, constrained optimization, numerical Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D02.03.02"},{"id":"D02.04.01","title":"Principal Components of Implied Volatility Index Curves","area":"Derivatives","family":"F01","difficulty":2,"gate":"pending","question":"How much of the variation in a common panel of short-, medium- and longer-horizon implied volatility indices can be explained by level, slope and curvature? Are principal components stable across market regimes?","motivation":"The term structure of option-implied volatility reflects common movements in risk as well as changes concentrated at short or long horizons. PCA describes these movements using a small number of statistical components. The key question is whether such compression remains informative outside the estimation period and across regimes, rather than whether a full-dimensional basis can reconstruct the sample.","prereq":"Linear algebra, time-series statistics, derivatives basics and Python pandas/NumPy.","design":"Empirical application","tags":["PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D02.04.01"},{"id":"D02.04.02","title":"Implied Volatility Surface Dynamics and Forecasting","area":"Derivatives","family":"F01","difficulty":3,"gate":"blocked","question":"Do dynamic factors of constant-maturity implied total variance outperform persistence and simple autoregressions for out-of-sample surface forecasts?","motivation":"A surface forecast must be evaluated on comparable contracts or coordinates through time. Dynamic factors may capture common movements, but apparent forecast skill can result from look-ahead interpolation or a basis estimated using test observations. This study tests factor forecasts against persistence and cellwise time-series benchmarks on a fixed, supported grid.","prereq":"Options, time-series forecasting, PCA, interpolation, Python; permitted longitudinal surface data.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","PCA \u0026 latent factors"],"data_note":"Licensed option surface history of at least 3 years and 500 usable sessions.","state":"description","href":"topic.html?id=D02.04.02"},{"id":"D03.01.01","title":"Forecasting Equity Market Volatility: GARCH versus Historical Volatility","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Does GARCH(1,1) improve genuinely out-of-sample forecasts of daily and 21-trading-day market variance relative to rolling historical variance? Is the ranking stable in high- and low-volatility periods?","motivation":"Volatility clusters in equity markets: large price movements tend to be followed by large movements, regardless of their sign. A conditional volatility model is useful only if it forecasts future risk more accurately than a simple historical benchmark. This question matters for risk limits, margin and derivative applications. The object here is physical-measure return variance, not the risk-neutral volatility embedded in option prices.","prereq":"Time-series econometrics, maximum likelihood basics, data handling, Python pandas/statsmodels/arch. No intraday feed required.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.01.01"},{"id":"D03.01.02","title":"Asymmetric Volatility and the Leverage Effect","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Do GJR-GARCH and EGARCH improve next-day and multi-day variance forecasts relative to symmetric GARCH, especially after negative market innovations?","motivation":"Negative equity returns are often followed by more volatile markets than equally large positive returns. A symmetric variance recursion cannot capture this asymmetry. The research separates the shape of the news-impact function from the ability of an estimated model to predict future variation.","prereq":"Maximum likelihood, time-series econometrics and Python arch/statsmodels. Understand conditional vs realized variance.","design":"Empirical application","tags":["Calibration \u0026 estimation","Time-series forecasting","Regression \u0026 inference","Simulation \u0026 Monte Carlo"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.01.02"},{"id":"D03.02.01","title":"Multi-Horizon Volatility Forecasting with HAR Models","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Do multi-scale variance components improve out-of-sample forecasts of average daily squared market returns at one-, five- and twenty-two-day horizons relative to GARCH and historical averages?","motivation":"Market variance evolves on multiple time scales. Daily, weekly and monthly histories may summarize persistent volatility without imposing a fully specified latent process. This thesis asks whether that parsimony improves genuine forecasts, not whether a richer regression fits the past.","prereq":"Time-series regression, GARCH, forecasting and Python (arch or equivalent).","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Calibration \u0026 estimation"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.02.01"},{"id":"D03.02.02","title":"Volatility Persistence and Long Memory in Financial Returns","area":"Derivatives","family":"F03","difficulty":3,"gate":"pending","question":"Does a fractional-memory model improve variance forecasts over HAR and conventional persistent volatility models, and can regime shifts mimic its apparent long memory?","motivation":"Slowly decaying dependence in volatility may reflect a fractional process, but persistent regime shifts can produce similar sample patterns. The project combines a controlled identification experiment with out-of-sample comparison to assess whether apparent long memory is useful for forecasting.","prereq":"Time-series econometrics, likelihood, fractional filters, statistical programming.","design":"Empirical application","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.02.02"},{"id":"D03.03.01","title":"Latent Stochastic Volatility versus GARCH","area":"Derivatives","family":"F03","difficulty":3,"gate":"pending","question":"Does a parsimonious latent stochastic volatility model improve daily predictive density and multi-day variance forecasts relative to GARCH?","motivation":"GARCH treats conditional variance as a deterministic function of past returns; stochastic volatility introduces an unobserved, evolving risk state. The empirical question is whether integrating over uncertainty about that state improves the predictive density and the variance forecast enough to justify the computational cost.","prereq":"Time-series likelihood, Monte Carlo, state-space methods, Python.","design":"Empirical application","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Time-series forecasting","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.03.01"},{"id":"D03.03.02","title":"Volatility Regimes and Crisis Forecasting","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Do filtered two-state volatility regimes improve short-horizon variance and stress-event forecasts relative to GARCH and simple historical variance?","motivation":"Markets may move between calm and turbulent conditions rather than evolve through a single smooth variance process. A two-state model can express this possibility, but useful stress forecasting requires probability calibration on future observations, not a convincing retrospective classification of crises.","prereq":"Time series, likelihood, simulation, probability, Python.","design":"Empirical application","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Time-series forecasting","PCA \u0026 latent factors","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.03.02"},{"id":"D03.04.01","title":"Does the VIX Improve Realized Volatility Forecasts?","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Does lagged VIX improve one-month physical variance forecasts relative to historical and GARCH-based forecasts in genuine chronological evaluation?","motivation":"Option prices contain forward-looking information about variation, but implied variance is not the physical expectation that a forecaster wishes to estimate. The project asks whether the VIX adds predictive information beyond returns-based models, while respecting horizon and underlying differences.","prereq":"Time series, GARCH, regression, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.04.01"},{"id":"D03.04.02","title":"Volatility-of-Volatility and the Forecasting of Extreme Volatility","area":"Derivatives","family":"F03","difficulty":2,"gate":"pending","question":"Does VVIX incrementally forecast extreme physical volatility over the next month after controlling for VIX and lagged realized variance?","motivation":"High volatility and uncertainty about volatility are distinct phenomena. VVIX measures option-implied variation of the volatility index; its incremental forecasting value should be assessed after controlling for the prevailing VIX level and past market variance. The focus is calibrated tail-event probabilities.","prereq":"Probability, logistic regression, time-series forecasting, Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D03.04.02"},{"id":"D04.01.01","title":"The Economics of Discrete-Time Delta Hedging","area":"Derivatives","family":"F04","difficulty":1,"gate":"not_required","question":"How rapidly does terminal replication error decline as delta rebalancing becomes more frequent, and which strikes, maturities and volatility states remain difficult to hedge?","motivation":"In the Black--Scholes economy, continuous trading eliminates replication risk. A trader who can rebalance only at discrete dates must instead bear the residual price risk accumulated between trades. More frequent trading reduces this exposure, but the trading volume needed to achieve a given precision can be substantial even when transaction costs are excluded. This project studies the economic magnitude and distribution of the residual risk, rather than simply reproducing the continuous-time formula.","prereq":"Stochastic calculus, BSM, simulation, Python arrays and basic statistical inference.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.01.01"},{"id":"D04.01.02","title":"The Role of Gamma in Delta-Hedging Errors","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"How accurately does a gamma-weighted quadratic-variation error explain discrete hedging losses across strikes and maturities, and when does the approximation break down?","motivation":"A delta hedge removes first-order stock exposure at the trading instant, but not option curvature between trades. The project asks whether a local curvature expansion explains the economically important part of replication errors and where it breaks down.","prereq":"Stochastic calculus, BSM Greeks, Monte Carlo and numerical Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.01.02"},{"id":"D04.02.01","title":"Delta-Vega Hedging under Stochastic Volatility","area":"Derivatives","family":"F04","difficulty":3,"gate":"not_required","question":"When does a second traded vanilla option materially improve hedging of a target option in a stochastic-volatility market, net of rebalancing and conditioning risk?","motivation":"Stochastic variance introduces a shock that the stock alone generally cannot span. A second option can reduce this exposure, but a small variance sensitivity can demand extreme positions. The benefit of additional spanning must be measured net of trading and numerical conditioning.","prereq":"Stochastic calculus, options Greeks, Fourier integration, simulation and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.02.01"},{"id":"D04.02.02","title":"Historical Stress Paths and the Performance of Model-Based Option Hedges","area":"Derivatives","family":"F04","difficulty":2,"gate":"blocked","question":"How do BSM delta-hedging errors on observed index paths differ from errors on simulated GBM paths under the same synthetic pricing and rebalancing rules?","motivation":"Observed equity stress paths provide realistic sequences of price changes even without historical option quotes. Replaying hypothetical pricing and hedging rules on these paths isolates the effect of path behavior, but does not establish the returns of a traded options strategy.","prereq":"BSM and Greeks, simulation, time-series cleaning, portfolio accounting.","design":"Hybrid: simulation + historical replay","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"Historical SP500 price paths with permission and complete stress windows (hybrid simulation/replay).","state":"description","href":"topic.html?id=D04.02.02"},{"id":"D04.03.01","title":"Optimal Rebalancing Frequency with Transaction Costs","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"How does the optimal discrete delta-hedging frequency depend on transaction costs, volatility, maturity and the hedger's risk tolerance? Is the optimal frequency robust to model misspecification?","motivation":"Frequent rebalancing improves replication in a frictionless model, but each trade consumes resources. The relevant economic decision is a finite calendar chosen according to the hedger's risk tolerance and costs, not a universal optimal frequency.","prereq":"BSM, stochastic simulation, Greeks, basic optimization and Python. No derivatives or bid-ask history required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Constrained optimization","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.03.01"},{"id":"D04.03.02","title":"No-Trade Bands for Option Hedging","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"Can a delta-band policy reduce expected replication cost at a given tail hedging-error budget, compared with fixed-frequency rebalancing?","motivation":"A fixed calendar ignores how far the existing hedge has drifted from the current target. A no-trade band can save trading when that deviation is small. Compare state-dependent intervention against calendar strategies under a common tail-risk budget.","prereq":"BSM, stochastic calculus, simulation, risk measures and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Constrained optimization","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.03.02"},{"id":"D04.04.01","title":"Deep Hedging with Transaction Costs","area":"Derivatives","family":"F04","difficulty":3,"gate":"not_required","question":"Can a small neural hedging policy improve the net loss distribution of a short option relative to delta hedging and tuned no-trade bands at the same cost and risk objective?","motivation":"With frictions, a feasible hedge can depend on time, moneyness and the existing position. A flexible neural policy may exploit this state dependence, but apparent gains can result from overfitting or unequal constraints. The project tests economic value against strong tuned benchmarks.","prereq":"Options, numerical simulation, optimization, basic neural networks and Python.","design":"Simulation","tags":["Simulation \u0026 Monte Carlo","Constrained optimization","Machine learning","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.04.01"},{"id":"D04.04.02","title":"Hedging with Model-Free Regression Policies","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"Can transparent regression hedges improve on BSM delta when the underlying follows a stochastic-volatility or jump process and the policy is trained without access to true model parameters?","motivation":"Transparent regression hedges offer a structural-model alternative when model parameters are unavailable. Their value depends on observable features that predict useful conditional covariances. The question is whether a richer feasible basis improves replication on independent paths.","prereq":"BSM, regression, Monte Carlo, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Regression \u0026 inference","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D04.04.02"},{"id":"D05.01.01","title":"Variance Reduction in Monte Carlo Option Pricing","area":"Derivatives","family":"F02","difficulty":1,"gate":"not_required","question":"Which of antithetic variates, control variates and their combination yields the best pricing precision per unit runtime for European and discretely monitored Asian calls? Does the efficiency ranking depend on moneyness?","motivation":"Monte Carlo pricing is attractive for path-dependent claims, but a small standard error need not imply computational efficiency. Variance reduction changes the sampling procedure rather than the pricing model. The project asks which methods save computation for the same payoff and why the gains depend on moneyness and averaging.","prereq":"Probability, risk-neutral valuation, basic statistics, Python vectorization. Suitable for a student developing quantitative programming skills.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Regression \u0026 inference"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.01.01"},{"id":"D05.01.02","title":"Quasi-Monte Carlo Methods for Path-Dependent Options","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"When do scrambled Sobol sequences and Brownian bridge ordering improve the accuracy and runtime of Asian option pricing compared with plain Monte Carlo?","motivation":"Even a simple diffusion generates high-dimensional integration problems when payoffs depend on many observations. Low-discrepancy sampling changes the integration design; bridge ordering changes which Gaussian coordinates represent important path variation. The thesis evaluates both mechanisms while preserving the payoff and observation dates.","prereq":"Monte Carlo, multivariate normals, Python SciPy qmc and numerical benchmarking. No market data required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.01.02"},{"id":"D05.02.01","title":"Binomial Trees versus Finite Differences for American Options","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do a CRR binomial tree and an implicit finite-difference obstacle solver compare in American put prices, exercise boundaries and computational efficiency?","motivation":"American puts require a stopping decision as well as a valuation. Two algorithms may agree on inception price yet imply different exercise boundaries, which matter economically. The thesis compares a binomial lattice and an implicit obstacle solver while holding the economic model and contract fixed.","prereq":"Derivatives pricing, numerical linear algebra, PDE basics and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","PDE, trees \u0026 Fourier","Constrained optimization"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.02.01"},{"id":"D05.02.02","title":"Numerical Stability in Finite-Difference Option Pricing","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do explicit, backward-Euler and Crank-Nicolson methods differ in stability, oscillations and accuracy when the option payoff is nonsmooth?","motivation":"A scheme that prices a smooth claim accurately may oscillate near a vanilla kink or a digital discontinuity. Even a small price error can conceal large Greek errors. The project isolates stability, monotonicity and convergence of time-stepping schemes in the same European pricing problem.","prereq":"Numerical linear algebra, PDEs, BSM and Python/SciPy.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.02.02"},{"id":"D05.03.01","title":"Fourier-Based Option Pricing: Accuracy and Computational Efficiency","area":"Derivatives","family":"F02","difficulty":3,"gate":"not_required","question":"At a specified error tolerance, when is FFT inversion more efficient than direct quadrature for European option pricing?","motivation":"Transform methods are useful when the terminal law has a characteristic function but no simple option formula. A large batch of strikes may justify FFT setup, while a few queries may favor quadrature. The thesis compares speed at controlled pricing error, not merely the elapsed time of two implementations.","prereq":"Complex numbers, Fourier transforms, stochastic volatility, numerical analysis.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","PDE, trees \u0026 Fourier","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.03.01"},{"id":"D05.03.02","title":"The COS Method for Pricing Options with Non-Gaussian Returns","area":"Derivatives","family":"F02","difficulty":3,"gate":"not_required","question":"When does COS pricing achieve a given error tolerance faster than direct Fourier quadrature, and which truncation choices fail for non-Gaussian returns?","motivation":"Cosine expansion replaces inversion by a finite series of payoff coefficients and characteristic-function values. Rare jumps can make a visually converged series inaccurate because important probability mass lies outside the approximation interval. The study examines interval width and series length separately.","prereq":"Fourier analysis, risk-neutral valuation, numerical integration and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","PDE, trees \u0026 Fourier","Stochastic processes"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.03.02"},{"id":"D05.04.01","title":"Discretizing the Heston Model: Bias, Stability and Computational Cost","area":"Derivatives","family":"F02","difficulty":3,"gate":"not_required","question":"Which time-discretization schemes achieve reliable Heston prices at a fixed computation budget, including near-boundary parameter regimes?","motivation":"Under stochastic volatility the variance can approach zero, where Euler approximations may produce negative latent states or distorted stock dynamics. A nonnegative variance scheme is not necessarily an accurate pricer. This project compares weak pricing bias and computational cost, including near-boundary regimes.","prereq":"SDEs, Monte Carlo, characteristic functions, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.04.01"},{"id":"D05.04.02","title":"Estimating Option Greeks with Monte Carlo Methods","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"Which of bump-and-revalue, pathwise and likelihood-ratio estimators delivers the best accuracy-cost trade-off for delta and vega of European calls, digitals and Asian options?","motivation":"Hedging and risk management require sensitivities of derivative values, not just accurate prices. Differentiating a simulated price introduces a second numerical problem: the estimator must resolve a change in the payoff without allowing sampling noise to overwhelm it. For a digital option, the payoff jumps at the strike; differentiating individual sample paths misses that jump. An arithmetic Asian option provides a different challenge because every fixing affects the payoff. Comparing estimators across these contracts reveals when a theoretically valid sensitivity can be estimated efficiently.","prereq":"BSM, calculus, probability, Monte Carlo, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D05.04.02"},{"id":"D06.01.01","title":"Asian Option Pricing and the Value of Averaging","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do the averaging window, monitoring frequency and volatility affect arithmetic and geometric Asian call prices and their hedge sensitivities relative to a European option?","motivation":"Averaging reduces exposure to any single observation, but moving the averaging dates also changes expected levels when carry is nonzero. This project separates monitoring frequency from averaging window and asks how both price and hedge sensitivities differ from terminal exposure.","prereq":"Lognormal distributions, BSM, Monte Carlo and Python. No external data required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.01.01"},{"id":"D06.01.02","title":"Barrier Options and Discrete Monitoring Risk","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How large is discrete-grid bias in pricing a continuously monitored down-and-out call, and how effectively can a Brownian bridge remove it? How does the economic price difference for a genuinely discretely monitored contract vary with barrier proximity?","motivation":"Barrier prices depend on whether a threshold is observed continuously or only at specified dates. A discrete simulation can reproduce one contract exactly while approximating another badly. Near the barrier, unobserved crossings make this economic distinction particularly important.","prereq":"Brownian motion, BSM, conditional probabilities, simulation and numerical statistics. No historical options required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.01.02"},{"id":"D06.02.01","title":"The Early Exercise Premium of American Options","area":"Derivatives","family":"F02","difficulty":1,"gate":"not_required","question":"When is early exercise optimal and how much does the exercise right contribute to the value of American calls and puts?","motivation":"An American exercise right depends on the opportunity cost of waiting, forgone dividends and future payoff uncertainty. The focus is economic comparative statics, not algorithm rankings. The project studies the value of exercise for calls and puts and the response of the boundary to carry.","prereq":"Derivatives pricing, probability, Python arrays and basic numerical methods.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.02.01"},{"id":"D06.02.02","title":"Least-Squares Monte Carlo for Bermudan Options","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do regression basis, training size and exercise frequency affect the value and quality of a least-squares Monte Carlo stopping policy?","motivation":"Least-squares Monte Carlo learns a stopping policy by approximating conditional continuation. Regression fit need not predict policy quality: exercise is a nonlinear decision, and evaluating on training paths invites selection bias. The project evaluates frozen policies independently.","prereq":"Conditional expectation, Monte Carlo, least squares and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Regression \u0026 inference"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.02.02"},{"id":"D06.03.01","title":"Pricing and Risk Decomposition of Capital-Protected Notes","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do yield level, volatility, fees and issuer credit affect attainable equity participation and the economic value of principal protection?","motivation":"Principal protection uses part of issue proceeds to finance a promised maturity floor, leaving a residual budget for equity exposure. Low yields, fees and issuer credit therefore affect attainable participation. The project studies the financing constraint and distinguishes promised from reliable protection.","prereq":"BSM, discount curves, default intensity basics, simulation.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Cash-flow valuation","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.03.01"},{"id":"D06.03.02","title":"Autocallable Notes: Pricing and Embedded Risk","area":"Derivatives","family":"F02","difficulty":3,"gate":"not_required","question":"How do autocall and downside barriers change fair coupon, expected life and tail loss, and how sensitive are valuations to volatility, dividends and issuer credit?","motivation":"An autocallable note couples coupon and repayment timing to the path of observed equity prices. The coupon cannot be interpreted independently of expected life and downside exposure. The project uses one precise contract to study these trade-offs, rather than treating all notes as the same payoff.","prereq":"Risk-neutral pricing, Monte Carlo, derivative Greeks and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Cash-flow valuation","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.03.02"},{"id":"D06.04.01","title":"Basket and Worst-of Options: The Role of Correlation","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do correlation and volatility heterogeneity affect arithmetic basket calls and worst-of puts, and when does the sign of correlation sensitivity differ?","motivation":"Dependence affects a payoff on the average differently from a payoff on the minimum. The former depends on basket dispersion, while the latter is exposed to joint tail events. The project keeps marginal asset laws fixed and studies how admissible correlation changes alter both claims.","prereq":"Multivariate normal distribution, risk-neutral pricing, Monte Carlo, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.04.01"},{"id":"D06.04.02","title":"Quanto Options and Currency Risk in International Derivatives","area":"Derivatives","family":"F02","difficulty":2,"gate":"not_required","question":"How do FX volatility and equity-FX correlation affect quanto prices and deltas relative to ordinary foreign options converted at spot?","motivation":"Fixing currency conversion removes direct exchange-rate exposure at settlement but changes the pricing-measure equity drift. The quanto correction depends on risk-neutral equity–FX covariance. The study separates fixed, random and spot conversion, and evaluates both price and equity-delta exposure.","prereq":"Ito calculus, BSM, change of numeraire, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D06.04.02"},{"id":"D07.01.01","title":"From Discount Curves to Interest Rate Swap Prices","area":"Derivatives","family":"F05","difficulty":2,"gate":"pending","question":"How do curve shape and interpolation choices affect hypothetical single-curve par swap rates and PV01/key-rate risk across maturities? When are differences economically material for a fixed notional?","motivation":"Discount curve interpolation changes forward rates and can therefore change hypothetical swap values even when two methods reproduce all quoted zero-yield nodes. Measure the economic magnitude in basis points and currency units for fixed contracts, keeping the single-curve abstraction explicit.","prereq":"Fixed income, discount factors, calculus and interpolation, Python pandas/SciPy. No actual swap dealer quotes needed.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Cash-flow valuation","Fixed income \u0026 curves","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D07.01.01"},{"id":"D07.01.02","title":"Interest Rate Swaps and the Management of Duration Risk","area":"Derivatives","family":"F05","difficulty":2,"gate":"pending","question":"How much interest rate risk can a stylized payer swap eliminate from a government bond portfolio, and when do key-rate hedges outperform a single DV01 hedge?","motivation":"A payer swap can offset the duration of a long fixed-income portfolio, yet a single parallel sensitivity leaves exposure to twists and convexity. Compare a single swap hedge with a key-rate hedge on identical historical curve shocks at fixed cash-flow schedules.","prereq":"Fixed-income pricing, linear algebra, Python and basic portfolio risk analysis.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Cash-flow valuation","Constrained optimization","Fixed income \u0026 curves","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D07.01.02"},{"id":"D07.02.01","title":"Calibrating Hull-White to the Initial Yield Curve","area":"Derivatives","family":"F05","difficulty":2,"gate":"not_required","question":"How does Hull-White exact initial-curve fitting affect bond-option prices, and how much valuation uncertainty remains after all models fit the same curve?","motivation":"Exact fitting of today's discount curve removes cross-model discrepancies due to initial term structures, but cannot identify future rate volatility or mean reversion. Study how this distinction translates into bond-option values across the specified curve shapes and parameter configurations.","prereq":"Fixed income, Gaussian processes, stochastic discounting and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D07.02.01"},{"id":"D07.02.02","title":"Interest Rate Options under Gaussian and Square-Root Dynamics","area":"Derivatives","family":"F05","difficulty":2,"gate":"not_required","question":"After matching initial bond prices and at-the-money option volatility approximately, how do Gaussian and square-root dynamics affect out-of-the-money bond options and their Greeks?","motivation":"Gaussian and square-root models can agree on today's curve and one liquid at-the-money bond option while implying different tails and sensitivities. A controlled comparison isolates those distributional implications rather than confounding them with different fitted term structures.","prereq":"Stochastic calculus, affine processes, fixed-income pricing, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D07.02.02"},{"id":"D07.03.01","title":"Black versus Bachelier Pricing in Low-Rate Environments","area":"Derivatives","family":"F05","difficulty":2,"gate":"not_required","question":"After matching an ATM premium, how do Black, shifted Black and Bachelier pricing differ across strikes and rate levels?","motivation":"Rate options can be quoted in normal, lognormal or shifted-lognormal volatility. Equal numerical volatility inputs do not represent equal economic uncertainty. Compare the models after matching a common ATM premium, including rate environments in which unshifted Black is not admissible.","prereq":"Fixed income, option pricing, normal distribution, numerical roots and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D07.03.01"},{"id":"D07.03.02","title":"Swaption Pricing and the Impact of Yield Curve Volatility","area":"Derivatives","family":"F05","difficulty":3,"gate":"not_required","question":"How do volatility level and mean reversion affect European payer swaption prices and hedge sensitivities across expiry and tenor in a one-factor Hull–White model fitted to consistent initial yield curves?","motivation":"The discount curve determines the present value of deterministic cash flows, but not the distribution of future swap rates. A model can match today's discount factors exactly and still leave material uncertainty about the value of an option on a swap. This project studies how the level and persistence of rate volatility affect optionality and hedging across expiry and tenor, holding the initial curve fixed.","prereq":"Fixed income, Gaussian diffusions, options, simulation and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Fixed income \u0026 curves","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D07.03.02"},{"id":"D07.04.01","title":"HJM and the No-Arbitrage Dynamics of Forward Rates","area":"Derivatives","family":"F05","difficulty":3,"gate":"not_required","question":"How does the HJM drift restriction discipline the evolution of discount bond prices, and how large are discretization errors when a continuous-time no-arbitrage model is implemented on a finite grid?","motivation":"The HJM drift restriction ties forward-rate changes to discount-bond no-arbitrage. Finite grids can violate the continuous-time martingale identity numerically even when the model is correct. Distinguish this error from a genuinely misspecified zero-drift forward model.","prereq":"Stochastic calculus, bond math, Gaussian processes, numerical quadrature, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D07.04.01"},{"id":"D07.04.02","title":"One-Factor versus Two-Factor Models for Interest Rate Hedging","area":"Derivatives","family":"F05","difficulty":3,"gate":"pending","question":"How much additional interest rate risk can a two-factor hedge remove relative to a one-factor hedge, after controlling for estimation error and gross notional?","motivation":"Yield-curve changes can span more than one empirically important direction. Additional hedge instruments may remove a second factor, but unstable estimated loadings and large notionals can offset the benefit. Test risk reduction on genuinely subsequent curve shocks.","prereq":"Fixed income, linear algebra, PCA, Python and regression.","design":"Empirical application","tags":["Cash-flow valuation","Constrained optimization","Fixed income \u0026 curves","Hedging \u0026 trading costs","PCA \u0026 latent factors"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D07.04.02"},{"id":"D08.01.01","title":"Variance Swap Pricing and Discrete Monitoring Bias","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"How large is the discrete-monitoring correction to variance-swap fair strikes in diffusion and jump-diffusion models, and how much of the difference from log-contract replication is due to jumps rather than discretization?","motivation":"Variance swaps exchange sampled squared log returns against a fixed strike. Continuous log-contract replication relies on path continuity; jumps introduce an additional economic correction. Separate sampling error from the jump correction.","prereq":"Ito calculus, risk-neutral pricing, compound Poisson processes, Monte Carlo and numerical integration.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","PDE, trees \u0026 Fourier"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D08.01.01"},{"id":"D08.01.02","title":"The Convexity Adjustment in Volatility Swap Pricing","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"How does volatility-of-volatility, maturity and mean reversion affect the convexity adjustment in volatility swap pricing?","motivation":"A volatility swap is sensitive to the distribution of future integrated variance rather than only its expectation. The research measures when a second-order convexity adjustment is economically adequate and when a nonlinear numerical benchmark is needed.","prereq":"Risk-neutral pricing, stochastic calculus basics, Monte Carlo and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D08.01.02"},{"id":"D08.02.01","title":"Modeling the VIX Futures Curve under Mean Reversion","area":"Derivatives","family":"F04","difficulty":3,"gate":"not_required","question":"How do the current variance state, mean reversion and volatility-of-volatility jointly shape a model-implied VIX futures curve?","motivation":"The VIX futures curve reflects both risk-neutral mean reversion and the distribution of future variance. The nonlinear square-root expectation separates state and convexity effects that would be conflated by taking the square root of expected variance.","prereq":"Risk-neutral valuation, square-root diffusions, noncentral chi-square distribution and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D08.02.01"},{"id":"D08.02.02","title":"VIX and VVIX as Indicators of Volatility Derivative Risk","area":"Derivatives","family":"F04","difficulty":2,"gate":"pending","question":"Does VVIX contain incremental information beyond VIX about near-term equity downside risk, and are their joint stress signals stable out of sample?","motivation":"A high implied-volatility level and uncertainty about that level are distinct signals. The question is whether VVIX improves near-term equity downside forecasts after controlling for VIX, not whether subtracting the two indices identifies a risk premium.","prereq":"Derivatives concepts, logistic regression, time-series validation and Python.","design":"Empirical application","tags":["Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D08.02.02"},{"id":"D08.03.01","title":"Covered Calls versus Buy-and-Hold: Risk and Performance","area":"Derivatives","family":"F04","difficulty":2,"gate":"blocked","question":"How much upside does a covered-call benchmark sacrifice, and does its downside protection survive comparison with a volatility-matched equity/cash portfolio?","motivation":"Covered-call indices can display lower volatility because some equity upside is sold. Comparing with unscaled buy-and-hold confounds reduced risk exposure with insurance value. Evaluate against a feasible lagged risk-matched equity/cash portfolio.","prereq":"Option payoffs, total returns, portfolio metrics, regression and bootstrap.","design":"Empirical application","tags":["Regression \u0026 inference","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"Authorized BXM index history and comparable benchmark.","state":"description","href":"topic.html?id=D08.03.01"},{"id":"D08.03.02","title":"Put Writing and the Compensation for Downside Risk","area":"Derivatives","family":"F04","difficulty":2,"gate":"blocked","question":"Does the performance of a put-writing benchmark survive comparison with equity/cash portfolios at comparable ex-ante risk, particularly in turbulent markets?","motivation":"Cash-secured put writing earns premium while retaining nonlinear downside exposure. Its apparent return advantage may reflect different risk or collateral conventions. Test compensation against ex-ante risk-matched stock-cash portfolios.","prereq":"Option payoff algebra, portfolio statistics, time-series inference and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"Authorized PUT index history and comparable benchmark.","state":"description","href":"topic.html?id=D08.03.02"},{"id":"D08.04.01","title":"Protective Puts and the Cost of Crash Insurance","area":"Derivatives","family":"F04","difficulty":2,"gate":"blocked","question":"How much downside protection does a systematic protective-put strategy provide relative to buy-and-hold and risk-matched stock-cash allocations, and at what realized return cost?","motivation":"A rolling protective-put index may limit large losses at the cost of repeated insurance purchases. Its realized protection depends on contract design and market history, and must be compared with lower equity exposure rather than attributed mechanically to put premiums.","prereq":"Options, portfolio returns, risk measures, bootstrap, Python.","design":"Empirical application","tags":["Simulation \u0026 Monte Carlo","Regression \u0026 inference","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"Authorized PPUT index history and comparable benchmark.","state":"description","href":"topic.html?id=D08.04.01"},{"id":"D08.04.02","title":"Designing Cost-Constrained Tail Risk Hedges","area":"Derivatives","family":"F04","difficulty":2,"gate":"not_required","question":"For a fixed annual initial premium budget, how do a protective put, a put spread and a collar differ in expected shortfall, expected return and extreme-loss protection? Which rankings survive changes in the tail distribution and the volatility risk premium?","motivation":"A fixed insurance budget forces choices between strike protection, quantity and surrendered upside. Protective puts, spreads and collars insure different parts of the distribution. Compare feasible structures at equal wealth across physical tail scenarios.","prereq":"Vanilla option pricing, risk measures, simulation and elementary optimization. No proprietary quotes required.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Constrained optimization","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D08.04.02"},{"id":"D09.01.01","title":"The Merton Model and the Economics of Corporate Default","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How do leverage, asset volatility and debt maturity jointly determine physical default probabilities, risk-neutral debt values and equity leverage? When do default probability and credit spread move differently?","motivation":"Leverage gives creditors a nonlinear claim on firm assets. The same probability of default need not imply the same borrowing cost, because severity and the price of risk enter debt valuation. Study these distinctions in a transparent terminal-default economy before introducing contractual complexity.","prereq":"BSM option pricing, probability measures, comparative statics, Python. Elementary corporate finance and credit spread interpretation.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.01.01"},{"id":"D09.01.02","title":"Structural Credit Models with Early Default","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How do default-barrier level and recovery convention alter the credit spread term structure relative to a maturity-only Merton benchmark?","motivation":"A covenant can trigger default before debt matures even if the firm later recovers. Short maturity spreads therefore depend on the path of assets, not only the terminal distribution. Distinguish this effect from changes in recovery timing and contractual loss.","prereq":"Stochastic calculus, first-passage distributions, option pricing and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.01.02"},{"id":"D09.02.01","title":"Reduced-Form Credit Risk and the Term Structure of Default Probabilities","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"Can a parsimonious piecewise-constant intensity curve reproduce synthetic CDS par spreads, and how sensitive are inferred default probabilities to recovery and discretization?","motivation":"A CDS term structure constrains a collection of expected discounted default payments, rather than revealing physical default frequencies. The inverse problem becomes delicate when quotes are noisy or recovery is uncertain. Examine when a nonnegative hazard bootstrap is feasible and when regularization is necessary.","prereq":"Discounting, probability, numerical root finding, credit-risk basics.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Constrained optimization","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.02.01"},{"id":"D09.02.02","title":"Credit Default Swap Pricing and Recovery Risk","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How do changes in assumed recovery alter fair CDS spreads, mark-to-market and inferred default intensity, under an otherwise identical hazard model?","motivation":"Recovery affects the premium for new protection and the value of an existing CDS. These sensitivities have different meanings depending on whether one holds the default model fixed or recalibrates it to the same observed quote. Keep contractual coupon and par coupon distinct throughout.","prereq":"Fixed income, survival functions, numerical integration and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.02.02"},{"id":"D09.03.01","title":"Corporate Credit Quality Spreads and Macroeconomic Conditions","area":"Derivatives","family":"F06","difficulty":2,"gate":"blocked","question":"How do the level and changes of the Baa-Aaa quality spread relate to economic activity and financial uncertainty, and are these associations stable across recessions?","motivation":"Corporate quality spreads often widen in deteriorating economic conditions, but rating composition, maturity and liquidity can also move them. The study is descriptive: compare the Baa-Aaa yield difference across the business cycle without treating it as a pure default-risk measure.","prereq":"Fixed income, regression, time-series diagnostics, Python or R; no individual-bond data required.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves"],"data_note":"Documented permission for Moody’s AAA/BAA series and aligned macro inputs.","state":"description","href":"topic.html?id=D09.03.01"},{"id":"D09.03.02","title":"Do Corporate Bond Spreads Forecast Economic Downturns?","area":"Derivatives","family":"F06","difficulty":2,"gate":"pending","question":"Do corporate credit spreads and the excess bond premium improve recession forecasts relative to the Treasury term spread?","motivation":"Credit-market valuations may contain forward-looking information beyond the Treasury slope. Evaluate whether credit spreads and the excess bond premium add predictive value for a dated recession outcome, relative to a base-rate and term-spread benchmark, without treating a revised series as a genuine real-time forecast.","prereq":"Fixed income, logistic regression, time series and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Time-series forecasting","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D09.03.02"},{"id":"D09.04.01","title":"Counterparty Credit Risk and the Pricing of Uncollateralized Derivatives","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How do maturity, market volatility, hazard and recovery jointly shape unilateral CVA for an uncollateralized forward, and how sensitive is independence-based CVA to wrong-way risk?","motivation":"A forward contract can be fairly priced at inception yet expose its holder to a loss if the counterparty defaults before settlement. The potential loss depends on the future replacement value at the time of default, not on the contractual notional alone. A useful valuation adjustment therefore requires both a model of market risk and a model of default. This project quantifies their joint importance, and asks whether an independence approximation remains informative when default intensity responds to the underlying price.","prereq":"BSM, credit intensity, numerical integration, Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Fixed income \u0026 curves","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.04.01"},{"id":"D09.04.02","title":"Wrong-Way Risk and Credit Valuation Adjustment","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How much can wrong-way dependence alter unilateral CVA when the standalone default probabilities and exposure dynamics are held fixed?","motivation":"Standalone exposure and default probabilities are insufficient to determine a counterparty loss when the two risks depend on one another. Isolate the contribution of a specified joint distribution at fixed marginals, rather than changing both the intensity level and dependence.","prereq":"Risk-neutral pricing, copulas, credit risk, probability and MC.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D09.04.02"},{"id":"D10.01.01","title":"Modeling Commodity Spot Prices with Mean-Reverting Processes","area":"Derivatives","family":"F07","difficulty":2,"gate":"pending","question":"Does a mean-reverting log-spot model improve out-of-sample WTI monthly price forecasts relative to a random walk, and is any gain robust to horizon, regime and estimation window?","motivation":"Mean reversion is a natural feature of commodity-price models, but persistence is difficult to estimate and may not translate into better forecasts. Compare a physical-measure mean-reverting log-price model with a random walk, using the actual information available at each forecast origin.","prereq":"Stochastic processes, AR models, forecasting and Python statsmodels/SciPy. No futures dataset required.","design":"Empirical application","tags":["Stochastic processes","Calibration \u0026 estimation","Regression \u0026 inference","Time-series forecasting"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D10.01.01"},{"id":"D10.01.02","title":"Commodity Forward Curves and Convenience Yield","area":"Derivatives","family":"F07","difficulty":3,"gate":"not_required","question":"How do current net convenience yield, its persistence and its correlation with spot shocks affect the shape and risk of commodity forward curves?","motivation":"Physical inventory may provide benefits beyond its resale value: it facilitates production, helps satisfy unexpected demand and reduces the risk of stockouts. A constant cost-of-carry model captures only a restricted relation between spot and forward prices. A stochastic net convenience yield permits the forward curve's slope and sensitivity to shocks to vary over time. The project studies how this additional state changes curve shape and the distribution of curve risk, rather than attempting to infer convenience yields from spot prices alone.","prereq":"Stochastic calculus, Gaussian processes, derivatives and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Fixed income \u0026 curves"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D10.01.02"},{"id":"D10.02.01","title":"Commodity Price Risk and the Minimum-Variance Hedge Ratio","area":"Derivatives","family":"F07","difficulty":2,"gate":"pending","question":"How much does a Brent spot-proxy hedge reduce WTI price risk, and how stable is the estimated minimum-variance hedge ratio across horizons and market regimes?","motivation":"WTI and Brent price changes often co-move, but regional supply and delivery conditions can create substantial basis risk. A statistical Brent spot proxy may reduce WTI exposure; it is not a claim about a self-financing futures hedge.","prereq":"Derivatives fundamentals, covariance and regression, basic time series and Python.","design":"Empirical application","tags":["Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D10.02.01"},{"id":"D10.02.02","title":"Pricing Commodity Options under Mean Reversion","area":"Derivatives","family":"F07","difficulty":2,"gate":"not_required","question":"How does mean reversion affect the maturity pattern of option prices on commodity forwards, holding the initial forward curve fixed?","motivation":"Mean reversion dampens the effect of current shocks on distant delivery prices. Commodity options therefore depend on both option expiry and underlying delivery, even when the initial forward curve is held fixed. This experiment isolates that mechanism from curve fitting.","prereq":"Gaussian processes, risk-neutral pricing, Black formula, Monte Carlo.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D10.02.02"},{"id":"D10.03.01","title":"Covered Interest Parity and Synthetic FX Forward Rates","area":"Derivatives","family":"F07","difficulty":2,"gate":"pending","question":"How do the level and differential of short-term USD and EUR interest rates shape synthetic EUR/USD forward prices, and how sensitive is the result to rate conventions and proxy choice?","motivation":"Covered interest parity links a currency forward to two funded cash accounts, but published monthly money-market proxies need not be synchronized tradable quotes. Construct parity-implied forward points and analyze their sensitivity, without interpreting the result as observed cross-currency basis.","prereq":"Fixed income discounting, FX conventions, elementary calculus and Python data manipulation.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Cash-flow valuation","Fixed income \u0026 curves"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D10.03.01"},{"id":"D10.03.02","title":"Currency Hedging of US Equity Investments for Euro-Area Investors","area":"Derivatives","family":"F07","difficulty":2,"gate":"pending","question":"When does a quarterly synthetic currency hedge improve the risk-return profile of a euro investor holding US equities? How do hedge ratio, equity-FX covariance and financing carry affect the result?","motivation":"A euro investor holding US equities is exposed both to equity performance and to movements in the euro-dollar exchange rate. A principal hedge does not automatically remove FX exposure from subsequent equity gains, and the optimal hedge depends on covariance and financing carry.","prereq":"Portfolio variance, FX forwards, return compounding, basic time-series econometrics and Python.","design":"Empirical application","tags":["Pricing \u0026 no-arbitrage","Regression \u0026 inference","Portfolio optimization","Hedging \u0026 trading costs"],"data_note":"Core inputs have been mapped, but actual files, permissions, coverage and conventions have not been validated.","state":"description","href":"topic.html?id=D10.03.02"},{"id":"D10.04.01","title":"Currency Option Pricing and Interest Rate Differentials","area":"Derivatives","family":"F07","difficulty":1,"gate":"not_required","question":"How do domestic and foreign rates affect currency option prices and hedge ratios, and how much of the effect is mediated by forward moneyness?","motivation":"Currency options depend on two interest rates. Their effects operate through discounting and the forward, so a comparison at fixed spot strike differs from a comparison at matched forward moneyness. Hedging must account for interest on the foreign cash position.","prereq":"BSM, probability, FX conventions, basic Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Simulation \u0026 Monte Carlo","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D10.04.01"},{"id":"D10.04.02","title":"Exchange Rate Jumps and Currency Option Smiles","area":"Derivatives","family":"F07","difficulty":2,"gate":"not_required","question":"Holding the forward and ATM option price fixed, how do jump frequency, direction and size affect FX smile slope and wing prices?","motivation":"FX jump risk changes the relative prices of calls and puts in the wings. Holding the forward and the ATM option price fixed provides a controlled comparison of smile asymmetry and curvature instead of confounding jump effects with the overall volatility level.","prereq":"FX derivatives, jump processes, implied volatility and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","Simulation \u0026 Monte Carlo","Calibration \u0026 estimation","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D10.04.02"},{"id":"D11.01.01","title":"State Prices and the Fundamental Theorem of Asset Pricing","area":"Derivatives","family":"F06","difficulty":1,"gate":"not_required","question":"How does changing the payoff span or asset prices affect existence and uniqueness of state prices, replication and the possibility of arbitrage?","motivation":"The fundamental theorem connects absence of arbitrage to a positive valuation functional, and completeness to its uniqueness. Finite-state economies allow the link between payoff span, redundancy and pricing consistency to be made explicit and checked by portfolios, not only by solver output.","prereq":"Linear algebra, basic probability, introductory derivatives and Python; convex separation can be learned during the project.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization","Factor models \u0026 SDF"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.01.01"},{"id":"D11.01.02","title":"Risk-Neutral Probabilities and Change of Numeraire","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How can one verify that money-market and forward-measure valuation give identical prices even when interest rates are stochastic?","motivation":"Stochastic discounting makes the choice of pricing measure economically meaningful but not a source of pricing disagreement. A change of numeraire reallocates probability weights to make a different traded unit the reference asset. Verify the equivalence locally, including self-financing replication.","prereq":"Conditional probability, discrete-time asset pricing, linear algebra and Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier","Fixed income \u0026 curves","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.01.02"},{"id":"D11.02.01","title":"Recovering Risk-Neutral Densities from Option Prices","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How accurately can a nonnegative risk-neutral density and its tail probabilities be recovered from sparse and noisy option prices?","motivation":"A smooth option smile can mask severe instability in its second derivative. Recovering a risk-neutral distribution from limited noisy prices is an inverse problem whose economically useful outputs include tail probabilities, not simply a small quote fitting error.","prereq":"Option pricing, numerical differentiation, constrained least squares, linear programming.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Calibration \u0026 estimation","Constrained optimization","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.02.01"},{"id":"D11.02.02","title":"Risk-Neutral Moments and the Limits of Option-Implied Information","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How accurately can the variance, skewness and kurtosis of risk-neutral log returns be recovered from truncated and discretely sampled option strips?","motivation":"Option prices can identify moments of the risk-neutral return distribution with sufficiently rich strike coverage. Empirical implementations truncate option strips and amplify noise in higher moments. The study quantifies this information loss relative to known synthetic truth and support-conditional bounds.","prereq":"Option pricing, integration, probability moments, constrained optimization.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.02.02"},{"id":"D11.03.01","title":"No-Arbitrage Bounds for Contingent Claims in Incomplete Markets","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How do additional traded securities narrow no-arbitrage bounds for a nonreplicable payoff, and when do bounds collapse to a single price? How sensitive are bounds to incomplete state coverage and quote uncertainty?","motivation":"When traded securities do not span a claim, absence of arbitrage restricts prices without necessarily choosing a unique one. Study how new payoff directions, state coverage and bid-ask uncertainty change that interval, and distinguish closed mathematical endpoints from admissible interior prices.","prereq":"Linear algebra, no-arbitrage theory, linear programming, Python/SciPy. Mathematical proof and numerical construction are both important.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Constrained optimization","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.03.01"},{"id":"D11.03.02","title":"Robust Option Pricing under Uncertain Volatility","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How wide are robust upper and lower option values under bounded volatility, and why do non-convex payoffs differ from simple calls?","motivation":"A trader who cannot specify a unique future volatility process may instead consider all admissible volatilities inside a band. Robust valuation then responds to the curvature of the payoff, not merely to two constant-volatility prices.","prereq":"PDEs, stochastic control, BSM and numerical analysis; Python.","design":"Simulation","tags":["Pricing \u0026 no-arbitrage","Stochastic processes","PDE, trees \u0026 Fourier","Constrained optimization","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.03.02"},{"id":"D11.04.01","title":"Quadratic Hedging in Incomplete Markets","area":"Derivatives","family":"F06","difficulty":2,"gate":"not_required","question":"How does an unspanned shock alter minimum mean-square hedging error relative to an independence or delta benchmark, and which part of the loss cannot be hedged?","motivation":"Incomplete spanning leaves a residual component of a claim that a traded proxy cannot hedge. A quadratic loss criterion defines an optimal projection under a specified probability law, while not creating a unique preference-free price.","prereq":"Probability, conditional expectations, regression, Python.","design":"Simulation","tags":["Stochastic processes","Simulation \u0026 Monte Carlo","Regression \u0026 inference","Hedging \u0026 trading costs"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.04.01"},{"id":"D11.04.02","title":"Utility Indifference Pricing of Nonreplicable Claims","area":"Derivatives","family":"F06","difficulty":3,"gate":"not_required","question":"How do the unhedgeable component and risk aversion determine the utility indifference price relative to complete-market and actuarial benchmarks?","motivation":"Incomplete markets allow a claim to have different values to buyers and sellers who cannot trade away its residual risk. Exponential utility isolates the effect of risk aversion and the hedgeable component in a one-period economy, providing an economically interpretable comparison with actuarial and replication benchmarks.","prereq":"Expected utility, asset pricing, Gaussian moments, convex optimization.","design":"Simulation","tags":["Constrained optimization","Equilibrium \u0026 preferences","Hedging \u0026 trading costs","Tail risk \u0026 distributions"],"data_note":"No external dataset required for the core design; optional extensions may require data.","state":"description","href":"topic.html?id=D11.04.02"}]};
